-- Bali and the Ericeira coast: hand-checked coworking spaces, laptop-friendly cafes and public libraries.
--
-- Bali: Canggu, Pererenan, Umalas, Seminyak, Legian, Kuta, Uluwatu, Jimbaran, Nusa Dua, Sanur, Denpasar,
-- Ubud, Amed, Candidasa, Lovina, Nusa Lembongan and Nusa Penida. Ericeira region (Portugal): Ericeira, Ribamar,
-- Mafra, Torres Vedras, Santa Cruz and Lourinha.
--
-- Researched in November 2026 from each venue's own website and official pages (municipal library portals,
-- operators' price pages) and from at least two independent listings or reviews where a venue has no site, then
-- re-checked by an independent pass that re-opened every source (checked_on 2026-11-15). Prices and hours are the
-- ones published there; where sources disagreed or nothing was published, hours stay empty and the access note says
-- "check before going". Bali prices are IDR and only appear in the description: places.day_pass_price_cents is
-- shown as euro. Closed venues, venues that only admit residents or members of a club, restaurants without a
-- laptop culture and venues that could not be placed on the map were left out.
--
-- Coordinates: Nominatim / OpenStreetMap (ODbL) or the venue's own map pin. `coord_precision` 'street' means only the
-- street was certain; such a venue is matched to an OpenStreetMap place of the same name within 500 m and then
-- keeps the OpenStreetMap coordinates, otherwise it is added at the street coordinate.
--
-- A place that is already on the map (an OpenStreetMap place of the same category within 15 m, a library within
-- 60 m, or any place within 200 m with the same or a contained name) is enriched instead of duplicated: the curated
-- fields are written to that row and locked, so the crawler keeps them. Everything else is added as source 'admin'.
-- Cities that have not been imported yet are skipped, so run import-cities.mjs for the new hotspots first (or run this
-- again afterwards). Idempotent; never touches places of other categories or admin rows of another kind.

create or replace function pg_temp.nomad_nk(t text)
returns text
language sql
immutable
as $$
  select regexp_replace(
    lower(translate(t, 'áàâäãéèêëíìîïóòôöõúùûüçñÁÀÂÄÃÉÈÊËÍÌÎÏÓÒÔÖÕÚÙÛÜÇÑ', 'aaaaaeeeeiiiiooooouuuucnAAAAAEEEEIIIIOOOOOUUUUCN')),
    '[^a-z0-9]', '', 'g'
  )
$$;

create or replace function pg_temp.nomad_same_name(a text, b text)
returns boolean
language sql
immutable
as $$
  select pg_temp.nomad_nk(a) = pg_temp.nomad_nk(b)
      or (length(pg_temp.nomad_nk(a)) >= 5 and pg_temp.nomad_nk(b) like '%' || pg_temp.nomad_nk(a) || '%')
      or (length(pg_temp.nomad_nk(b)) >= 5 and pg_temp.nomad_nk(a) like '%' || pg_temp.nomad_nk(b) || '%')
$$;

do $nomad$
declare
  it record;
  v_city uuid;
  v_id uuid;
  v_osm boolean;
  v_street boolean;
  v_matched uuid[] := '{}';
  v_lock text[];
begin
  perform set_config('cosurfing.bulk', 'on', true);
  for it in
    select * from jsonb_to_recordset($items$
{"slug":"amed-espresso-amed","city":"amed","name":"Amed Espresso","category":"cafe","description":"Coffee shop on an inland side street in Purwakerti (Amed) that roasts on site. A travel blog measured about 68 Mbps Wi-Fi and describes air-conditioned seating and comfortable tables, and Google-based listings tag it good for working on a laptop. It turns into a lively bar-style spot on some late afternoons and evenings, so come early to focus.","address":"MJ6R+QQQ, Purwakerti, Abang, Karangasem Regency, Bali 80852, Indonesia","lat":-8.33804,"lng":115.64198,"phone":"+62 819-3954-2240","access":"open","access_note":"Walk in; no booking needed. Order food or drinks to use a table. Hours differ between listings, so check before going; gets noisy later in the day.","coord_precision":"venue"},
{"slug":"blue-earth-village-amed","city":"amed","name":"Blue Earth Village","category":"cafe","description":"Yoga retreat and hotel above Jemeluk Bay whose open-air work area and restaurant welcome visitors. Three sources (an Amed nomad guide, a travel blog and Finn's guide) report fast, stable Wi-Fi on a separate provider, free use of the work area and a Mount Agung view. It is open-air, hot at midday and food is pricey.","address":"Amed St, Jemeluk, Bunutan, Abang, Karangasem 80852","lat":-8.33805,"lng":115.66251,"outdoor_seating":"yes","access":"open","access_note":"Walk in; the work area is reported free for guests and visitors. Order from the restaurant; hours not verified.","coord_precision":"venue"},
{"slug":"cafe-peoplepoint-amed","city":"amed","name":"Cafe PeoplePoint","category":"cafe","description":"Czech-managed all-day cafe near Lipah Bay with air-conditioned indoor seating and outdoor tables, open since 2022. A travel blog, Finn's guide and a 2026 Bali Holiday Secrets article describe fast Wi-Fi and outlets; one blog notes the Wi-Fi was out on two visits. About 4-5 km from central Amed.","address":"Jl. Raya Amed, near Lipah Beach, Bunutan, Abang, Karangasem 80852","lat":-8.35077,"lng":115.68218,"website":"https://cafepeoplepoint.wixsite.com/cafe-peoplepoint","opening_hours":"Mo-Su 07:00-22:00","hours_source":"website","access":"open","access_note":"Walk in. Phone numbers differ between listings, so none is given.","coord_precision":"venue"},
{"slug":"good-stuff-cafe-eco-store-amed","city":"amed","name":"Good Stuff Cafe & Eco Store","category":"cafe","description":"Eco-focused cafe and zero-waste shop on Jl. Melasti in Amed. Guides report air conditioning, a few tables with power and workable but not always reliable Wi-Fi, and HappyCow lists free Wi-Fi; it is breezy and on a noisy road.","address":"Jl. Melasti, Purwakerti, Amed, Abang, Karangasem, Bali 80852","lat":-8.33555,"lng":115.63213,"opening_hours":"Mo-Su 07:30-22:00","hours_source":"listing","access":"open","access_note":"Walk in. Wi-Fi reported as workable rather than reliable; hours not verified.","coord_precision":"venue"},
{"slug":"md-amed","city":"amed","name":"MD Amed","category":"cafe","description":"Locally owned, air-conditioned cafe on Jl. I Ketut Natih that two guides describe as quiet and spacious with fast Wi-Fi, though seats can be uncomfortable. Located between Good Stuff and Oneway.","address":"Jl. I Ketut Natih, Purwakerti, Abang, Amed, Karangasem 80852","lat":-8.33476,"lng":115.63583,"phone":"+62 857-3915-0996","opening_hours":"Mo-Su 08:00-22:00","hours_source":"listing","access":"open","access_note":"Walk in. Directory listings show 08:00-22:00 daily; check before going.","coord_precision":"venue"},
{"slug":"oneway-espresso-amed","city":"amed","name":"Oneway Espresso","category":"cafe","description":"Award-winning latte-art cafe on Jl. I Ketut Natih in the main Amed strip. Guides describe AC, usable Wi-Fi (about 25 Mbps in one report) and four tables with power; it is the busiest cafe in town.","address":"Jl. I Ketut Natih, Purwakerti, Abang, Amed, Karangasem 80852","lat":-8.3339,"lng":115.63953,"access":"open","access_note":"Walk in. Busy at peak times; hours not verified.","coord_precision":"venue"},
{"slug":"la-timba-coworking-amed","city":"amed","name":"La Timba Coworking","category":"coworking","description":"Coworking space in the Bunutan Valley area of Amed with air-conditioned workspaces, Starlink Wi-Fi, a pool and terrace, plus private meeting-room rental and on-site apartments and scooter rental. Prices (website, Nov 2026; VAT status not stated): day pass 250,000 IDR, 5 workdays 1,000,000 IDR, month 3,000,000 IDR, private meeting room 500,000 IDR per day.","address":"Bunutan Riverside (after the bridge), Jl. Raya Amed, Bunutan, Abang, Karangasem, Bali 80852","lat":-8.35015,"lng":115.66894,"website":"https://latimba.net/","phone":"+62 857-3718-9979","access":"registration","access_note":"Book or message the team for a day, weekly or monthly pass; it is a small space in the Bunutan area, not in central Amed village.","coord_precision":"street"},
{"slug":"ounix-coffee-candidasa","city":"candidasa","name":"Ounix Coffee","category":"cafe","description":"Small two-floor café on Jalan Raya Candidasa overlooking rice fields, at the start of the road to Tenganan. A 2026 review and a directory say Wi-Fi is available and the air-conditioned downstairs room attracts a few laptop users, with outlets on the terrace. An Oct 2025 reviewer found the Wi-Fi slow, so it suits light work better than video calls.","address":"FHV7+Q2J, Jl. Raya Candidasa, Nyuh Tebel, Manggis, Karangasem, Bali, Indonesia","lat":-8.50554,"lng":115.56252,"opening_hours":"Mo-Su 08:00-23:00","hours_source":"listing","access":"open","access_note":"Walk in; no booking needed. Order food or drinks to use a table. Use the air-conditioned downstairs room for work; the rooftop is hot at midday. Service can be slow.","coord_precision":"venue"},
{"slug":"alchemy-canggu","city":"canggu","name":"Alchemy Canggu","category":"cafe","description":"Plant-based cafe and restaurant that Canggu nomad guides recommend for long sessions, with fast Wi-Fi reported. One guide says the laptop floor is the top one. Menu is entirely vegan.","address":"Jl. Tanah Barak No.1a, Canggu, Kuta Utara, Badung, Bali 80361","lat":-8.64806,"lng":115.13688,"website":"https://www.alchemybali.co/","phone":"+62 813-2576-4451","opening_hours":"Mo-Su 07:30-21:30","hours_source":"website","access":"open","access_note":"Walk in; order food or drinks to use a table. Laptop floor reported to be the top one.","coord_precision":"venue"},
{"slug":"amolas-cafe-canggu","city":"canggu","name":"Amolas Cafe","category":"cafe","description":"Cafe on a quiet back street with indoor air-conditioned seating, a garden and a pool. Nomad blogs describe spacious tables, plugs at most of them and reliable Wi-Fi, and say it is rarely crowded. The menu is reportedly limited to lighter food, and the garden gets hot by mid-morning.","address":"Jl. Raya Kayutulang No.16, Canggu, Kuta Utara, Badung, Bali 80361","lat":-8.64126,"lng":115.14623,"outdoor_seating":"yes","access":"open","access_note":"Hours differ between sources: check before going.","coord_precision":"venue"},
{"slug":"bean-cafe-canggu","city":"canggu","name":"Bean Cafe Canggu","category":"cafe","description":"A colourful, cosy cafe on Padang Linjong that opens very early (6am) and closes at 6pm, according to its own site. DeskBean describes strong Wi-Fi, air-conditioning and a fairly quiet working atmosphere, with brunch and pastries. Outlets are reported as limited, so seat choice matters.","address":"Jl. Canggu Padang Linjong No.18A, Canggu, Kec. Kuta Utara, Kabupaten Badung, Bali 80363","lat":-8.64222,"lng":115.13902,"website":"https://www.beancafebali.com/","phone":"+62 813-3928-5635","opening_hours":"Mo-Su 06:00-18:00","hours_source":"website","access":"open","access_note":"Walk-in customers; buy food or drinks. The venue's own site mentions quiet mornings with a laptop; Wi-Fi, air-conditioning and outlet details come from third-party reviews.","coord_precision":"street"},
{"slug":"blou-cafe-canggu","city":"canggu","name":"Blou Cafe Canggu","category":"cafe","description":"A poolside cafe inside the Ecozy Dijiwa resort in Canggu. A nomad guide describes a large upper air-conditioned floor with many plug points and good Wi-Fi that is often quiet, and says staff do not hassle you as long as you buy something. Hours differ between the resort page and blog posts, so the resort's own hours are used.","address":"Jl. Canggu Padang Linjong, Canggu, Kec. Kuta Utara, Kabupaten Badung, Bali 80361","lat":-8.64821,"lng":115.13122,"website":"https://dijiwasanctuaries.com/at/ecozycanggu/facility/blou-cafe-canggu","phone":"+62 361 6205588","opening_hours":"Mo-Su 07:30-21:30","hours_source":"website","access":"open","access_note":"Open to walk-in customers; guides say to order something and you can stay long. Upstairs workspace can fill up, so arriving before 9am is suggested.","coord_precision":"street"},
{"slug":"day-by-day-coffee-eatery-canggu","city":"canggu","name":"Day by Day Coffee & Eatery","category":"cafe","description":"A small, cosy neighbourhood cafe on Jl. Sempol known for sandwiches, breakfast and lunch deals and good coffee. Directories describe reliable Wi-Fi, plug sockets, a calm mood and (per several) air-conditioning. Opening hours differ between listings, so none are given.","address":"Jl. Sempol No.24, Pererenan, Kec. Mengwi, Kabupaten Badung, Bali 80361","lat":-8.63881,"lng":115.13804,"phone":"+62 822-2061-2361","access":"open","access_note":"Walk-in customers; buy food or drinks. Small cafe, so seating is limited at peak times.","coord_precision":"street"},
{"slug":"espressolab-bali-canggu","city":"canggu","name":"Espressolab Bali","category":"cafe","description":"The Bali branch of the Turkish Espressolab chain, a large, stylish coffee-and-dessert cafe on Jl. Raya Semat. The chain's store page lists Wi-Fi, and DeskBean and recent reviews describe cold air-conditioning, many outlets and comfortable seating. It can be busy and is priced above average for Bali.","address":"Jl. Raya Semat No.5, Tibubeneng, Kec. Kuta Utara, Kabupaten Badung, Bali 80361","lat":-8.65538,"lng":115.14141,"website":"https://espressolab.com/en/corporate/stores/bali-indonesia","access":"open","access_note":"Walk-in customers; buy food or drinks. Opening hours differ between listings, so none are given.","coord_precision":"street"},
{"slug":"gron-espresso-bar-kitchen-canggu","city":"canggu","name":"Gron Espresso Bar & Kitchen","category":"cafe","description":"A spacious espresso bar and kitchen on Jl. Raya Semat that Indonesian press and directories recommend for working from a cafe, citing Wi-Fi, sockets and air-conditioned rooms. DeskBean describes a calm interior that can get more social at peak times. Listings give 08:00-21:00 daily.","address":"Jl. Raya Semat No.1, Tibubeneng, Kec. Kuta Utara, Kabupaten Badung, Bali 80361","lat":-8.65513,"lng":115.14165,"phone":"+62 811-9698-810","opening_hours":"Mo-Su 08:00-21:00","hours_source":"listing","access":"open","access_note":"Walk-in customers; buy food or drinks. No official website was found (Instagram only).","coord_precision":"street"},
{"slug":"hungry-bird-coffee-roaster-canggu","city":"canggu","name":"Hungry Bird Coffee Roaster","category":"cafe","description":"Specialty coffee roaster in Berawa whose upstairs floor is the laptop area, while the ground floor is reportedly laptop-free. A nomad guide describes the upstairs as air-conditioned with big tables and a quiet atmosphere, though outlets are limited and the space is small. The same guide says it closes in the late afternoon.","address":"Jl. Raya Semat No.86, Tibubeneng, Canggu, Kuta Utara, Badung, Bali 80361","lat":-8.65597,"lng":115.14113,"access":"open","access_note":"Hours differ between sources: check before going.","coord_precision":"venue"},
{"slug":"jelajah-coffee-canggu","city":"canggu","name":"Jelajah Coffee Canggu","category":"cafe","description":"A small roastery cafe on Padang Linjong run by Jelajah Coffee Roasters, with a rustic leafy interior and a compact food menu. Directories and reviews describe good Wi-Fi, air-conditioning and a calm, work-friendly culture. Outlet counts are not documented.","address":"Jl. Canggu Padang Linjong No.85D, Canggu, Kec. Kuta Utara, Kabupaten Badung, Bali 80351","lat":-8.64686,"lng":115.13255,"phone":"+62 877-5238-9183","opening_hours":"Mo-Su 07:00-18:00","hours_source":"listing","access":"open","access_note":"Walk-in customers; buy coffee or food. Takes laptops per several directories; no official website was found.","coord_precision":"street"},
{"slug":"kembali-berawa-canggu","city":"canggu","name":"Kembali Berawa","category":"cafe","description":"A spacious healthy-food cafe and restaurant in Berawa (protein meals, salads, shakes, coffee). DeskBean notes a strong co-working habit among the tables, fast Wi-Fi and air-conditioning, with moderate outlets. Hours on its own site are described inconsistently, so none are given here.","address":"Jl. Pemelisan Agung, Jl. Pantai Berawa Gg. Cendana, Canggu, Tibubeneng, Kec. Kuta Utara, Kabupaten Badung, Bali 80361","lat":-8.66039,"lng":115.13684,"website":"https://kembali.pulsepowerhub.id/","phone":"+62 811-3960-8696","access":"open","access_note":"Walk-in customers; buy food or drinks. Laptop-friendliness comes from a third-party directory.","coord_precision":"street"},
{"slug":"koloni-canggu","city":"canggu","name":"Koloni","category":"cafe","description":"A green, air-conditioned cafe with a garden terrace on Jl. Raya Semat, described by several directories as comfortable and fairly quiet for working. Reviews report good Wi-Fi and sockets but also that the laptop-friendliness is mixed. An old review (2019) says laptops were not allowed inside after 7pm, so ask staff in the evening.","address":"Jl. Raya Semat No.1, Canggu, Tibubeneng, Kec. Kuta Utara, Kabupaten Badung, Bali 80361","lat":-8.65814,"lng":115.1402,"phone":"+62 812-3905-4545","opening_hours":"Mo-Su 08:00-22:00","hours_source":"listing","access":"open","access_note":"Walk-in customers; buy food or drinks. Laptop policy may be restricted in the evening based on an older review; confirm on arrival.","coord_precision":"street"},
{"slug":"little-engine-coffee-canggu","city":"canggu","name":"Little Engine Coffee","category":"cafe","description":"A small, relaxed all-day cafe (the Machinery group's little sibling) on the Batu Bolong strip, serving breakfast, lunch, coffee and smoothies. Listings describe quiet tables where people read or work, with Wi-Fi and a moderate number of outlets. Opening hours differ between listings, so they are not given here.","address":"Jl. Pantai Batu Bolong No.35, Canggu, Kec. Kuta Utara, Kabupaten Badung, Bali 80351","lat":-8.64766,"lng":115.13945,"access":"open","access_note":"Walk-in customers; buy a drink or food as usual. Third-party listings rate Wi-Fi as average to fast and outlets as adequate; no official site was found.","coord_precision":"venue"},
{"slug":"merch-cafe-amsterdam-canggu","city":"canggu","name":"Merch Cafe Amsterdam","category":"cafe","description":"A bright Dutch-run cafe on Jl. Sempol in Pererenan, with a separate coworking workspace next door. Directories report fast Wi-Fi and many outlets in the cafe, while the workspace is the quieter, air-conditioned option and has a minimum spend per BaliUntold. One recent review complains about loud music and a non-working socket outside.","address":"No.17-C, Jl. Sempol, Pererenan, Kec. Mengwi, Kabupaten Badung, Bali 80351","lat":-8.63869,"lng":115.13805,"phone":"+62 851-7348-3500","opening_hours":"Mo-Su 07:00-17:00","hours_source":"listing","access":"open","access_note":"Walk-in customers; buy food or drinks. The workspace next door is a separate paid or minimum-spend area; the cafe itself is laptop-friendly per third parties.","coord_precision":"street"},
{"slug":"miel-specialty-coffee-canggu","city":"canggu","name":"Miel Specialty Coffee","category":"cafe","description":"Glass-fronted, plant-filled specialty coffee cafe on Batu Bolong with two floors and a coworking room upstairs. Guides describe sockets and a calm crowd, and one reports reliable Wi-Fi (a 52 Mbps test is cited). Air-conditioning is reported inconsistently (one guide says the upstairs is fan-cooled). It closes earlier than most work cafes and call audio can drop when it is busy.","address":"Jl. Pantai Batu Bolong No.5, Canggu, Kuta Utara, Badung, Bali 80361","lat":-8.64274,"lng":115.14237,"access":"open","access_note":"Hours differ between sources: check before going.","coord_precision":"venue"},
{"slug":"mowie-s-bali-canggu","city":"canggu","name":"Mowie's Bali","category":"cafe","description":"A Gili Air-inspired cafe in Berawa with a pool that guests can use. Its own site says Wi-Fi is fast and free and that a long table at the back suits laptop work, with plenty of outlets. Because it is a poolside cafe, expect some leisure traffic, especially on weekends.","address":"Jl. Pantai Berawa No.101x, Tibubeneng, Canggu, Kec. Kuta Utara, Kabupaten Badung, Bali 80361","lat":-8.66066,"lng":115.13999,"website":"https://mowiesbali.com/","phone":"+62 819-3403-3503","opening_hours":"Mo-Su 07:30-21:00","hours_source":"website","access":"open","access_note":"Walk-in customers; no booking needed according to the venue. Laptop and outlet claims are from the venue's own site; independent confirmation was not found.","coord_precision":"street"},
{"slug":"my-happy-place-canggu","city":"canggu","name":"My Happy Place","category":"cafe","description":"A colourful, cosy cafe on Jl. Nelayan with upstairs seating and board games. Directories mention reliable Wi-Fi and strong coffee and suggest it works best for relaxed laptop sessions earlier in the day. Outlet availability is unconfirmed.","address":"Jl. Nelayan No.19, Canggu, Kec. Kuta Utara, Kabupaten Badung, Bali 80351","lat":-8.65508,"lng":115.13516,"website":"https://myhappyplacebali.com/","phone":"+62 878-9882-2934","access":"open","access_note":"Walk-in customers; buy food or drinks. Laptop-friendliness comes from third-party directories; listings give different closing times (17:00-18:00), so check before going.","coord_precision":"street"},
{"slug":"nyom-nyom-coffee-canggu","city":"canggu","name":"Nyom Nyom Coffee","category":"cafe","description":"An open-air coffee shop with rooftop seating on Pantai Berawa. Its own site describes it as a cosy place to relax or work, and directories note reliable Wi-Fi and a laptop-friendly crowd. There is no air-conditioning, so breezy upstairs seating is the better bet, and it can get lively.","address":"Jl. Pantai Berawa Br Pelambingan No 37B, Tibubeneng, Canggu, Kec. Kuta Utara, Kabupaten Badung, Bali 80361","lat":-8.65747,"lng":115.14727,"website":"https://nyomnyomcoffee.com/","phone":"+62 819-9820-6999","opening_hours":"Mo-Su 07:00-22:00","hours_source":"website","access":"open","access_note":"Walk-in customers; buy food or drinks. The venue's own site calls it a cosy place to relax or work.","coord_precision":"street"},
{"slug":"nude-cafe-berawa-canggu","city":"canggu","name":"nüde cafe Berawa","category":"cafe","description":"A polished tropical-modern cafe on Pantai Berawa that is part of the nüde group. DeskBean calls it laptop-friendly with excellent coffee and air-conditioning, but warns of noise at peak brunch times and only average Wi-Fi. Visit off-peak for focused work.","address":"Jl. Pantai Berawa No.86, Tibubeneng, Kec. Kuta Utara, Kabupaten Badung, Bali 80361","lat":-8.66008,"lng":115.14079,"website":"https://nude-bali.com/locations/berawa","phone":"+62 852-3821-4003","opening_hours":"Mo-Su 07:00-23:00","hours_source":"website","access":"open","access_note":"Walk-in customers; buy food or drinks. Third-party sources rate Wi-Fi as average, so test it before a call.","coord_precision":"street"},
{"slug":"poul-canggu","city":"canggu","name":"Poul","category":"cafe","description":"A small, quiet cafe off the main road on Jl. Subak Canggu near the rice fields, known for burgers, avocado sandwiches and friendly service. DeskBean describes reliable Wi-Fi, big tables and good air-conditioning, and a directory summary says guests find the seats comfortable for relaxing or working. Opening hours differ between listings, so none are given.","address":"Jl. Subak Canggu, Canggu, Kec. Kuta Utara, Kabupaten Badung, Bali 80361","lat":-8.64957,"lng":115.14063,"phone":"+62 878-4600-0081","access":"open","access_note":"Walk-in customers; buy food or drinks. Third-party sources only.","coord_precision":"street"},
{"slug":"samm-s-farm-canggu","city":"canggu","name":"Samm's Farm","category":"cafe","description":"Canggu cafe with two floors, both described by a nomad blog as laptop-friendly. That blog and a second guide mention an air-conditioned upstairs workroom with a large communal table, plenty of outlets and fast Wi-Fi. The ground-floor courtyard is reportedly warmer.","address":"Jl. Canggu Padang Linjong No.58, Canggu, Kuta Utara, Badung, Bali","lat":-8.64566,"lng":115.13543,"phone":"+62 853-5369-5751","access":"open","access_note":"Hours differ between sources: check before going.","coord_precision":"venue"},
{"slug":"sari-kitchen-community-canggu","city":"canggu","name":"Sari Kitchen & Community","category":"cafe","description":"A large, multi-level all-day hangout near the Batu Bolong beach end, with open-air mezzanines and an air-conditioned lounge according to its own site. Directories list it as a good place for longer laptop sessions, especially upstairs. It has one of the bigger free car and scooter parking areas in Canggu and also hosts events, so it can be busy.","address":"Jl. Pantai Batu Bolong No.2A, Canggu, Kec. Kuta Utara, Kabupaten Badung, Bali 80361","lat":-8.65759,"lng":115.13116,"website":"https://www.saricanggu.com/","phone":"+62 821-4582-2655","access":"open","access_note":"Walk-in customers; buy food or drinks. Laptop-friendliness comes from third-party directories; the venue's own site does not mention it.","coord_precision":"venue"},
{"slug":"satusatu-coffee-company-canggu","city":"canggu","name":"SATUSATU Coffee Company","category":"cafe","description":"A specialty-coffee cafe on Pantai Berawa that is part of a coffee-plantation family business. Guides describe a small, quiet upstairs area meant for focused work or calls, with reliable Wi-Fi but few plugs, so arrive early and with a charged laptop. Cooling is by fans in the main area according to one guide, and an AC upstairs room according to others.","address":"Jl. Pantai Berawa No.36, Tibubeneng, Kec. Kuta Utara, Kabupaten Badung, Bali 80361","lat":-8.65578,"lng":115.14757,"phone":"+62 878-6207-7011","access":"open","access_note":"Walk-in customers; buy coffee or food. The upstairs quiet area fills up early; no official website was found.","coord_precision":"venue"},
{"slug":"shirley-cafe-bali-canggu","city":"canggu","name":"Shirley Cafe Bali","category":"cafe","description":"Two-floor cafe among rice fields. Directory listings report free Wi-Fi and some outlets, with upstairs heat and midday crowds as drawbacks for long work sessions.","address":"Jl. Canggu Padang Linjong No.3, Canggu, Kuta Utara, Badung, Bali 80351","lat":-8.63693,"lng":115.14301,"access":"open","access_note":"Hours differ between sources: check before going.","coord_precision":"venue"},
{"slug":"slavic-roots-cafe-eatery-canggu","city":"canggu","name":"Slavic Roots Cafe & Eatery","category":"cafe","description":"A Berawa cafe with an upstairs workspace and rooftop views for after the work block. DeskBean reports strong Wi-Fi, air-conditioning and a calm atmosphere, with outlets only moderate. Sunday hours are shorter than the rest of the week.","address":"Jl. Pantai Berawa No.26, Tibubeneng, Kec. Kuta Utara, Kabupaten Badung, Bali 80361","lat":-8.65451,"lng":115.14799,"website":"https://slavicrootsbali.cafe/","phone":"+62 822-6631-7733","opening_hours":"Mo-Sa 08:00-22:00; Su 10:00-18:00","hours_source":"website","access":"open","access_note":"Walk-in customers; buy food or drinks. The venue's own site calls it perfect for long laptop sessions; Wi-Fi, air-conditioning and outlet details come from a third-party directory.","coord_precision":"street"},
{"slug":"the-avocado-factory-canggu","city":"canggu","name":"The Avocado Factory","category":"cafe","description":"All-avocado restaurant and cafe near Batu Mejan. Its own FAQ says free Wi-Fi is available and laptops are welcome on the terrace, while the air-conditioned indoor area is kept for dining from 10:00 to 15:00 and laptops are not allowed there in those hours. A Bali SIM guide lists it among Canggu work cafes for fast Wi-Fi. Order something, keep calls quiet and expect busy meal times.","address":"Jl. Batu Mejan Canggu, Canggu, Kuta Utara, Badung, Bali 80351","lat":-8.65222,"lng":115.1318,"website":"https://theavocadofactory.com/","phone":"+62 813-3738-2521","opening_hours":"Mo-Su 07:00-23:00","hours_source":"website","outdoor_seating":"yes","access":"open","access_note":"Laptops welcome on the terrace; not allowed indoors 10:00-15:00 (venue FAQ). Order food or drinks; kitchen last orders 22:30.","coord_precision":"venue"},
{"slug":"the-daun-coffee-and-roastery-canggu","city":"canggu","name":"The Daun Coffee and Roastery","category":"cafe","description":"Coffee roastery cafe on Jl. Nelayan that blog guides list among Canggu work cafes, with fast Wi-Fi reported. Guides say laptops are steered away from the ground floor. Its separate coworking room is reported to have closed, while the cafe itself is still trading.","address":"Jl. Nelayan No.10, Canggu, Kuta Utara, Badung, Bali 80361","lat":-8.65443,"lng":115.13559,"access":"open","access_note":"Hours differ between sources: check before going.","coord_precision":"venue"},
{"slug":"the-shady-shack-canggu","city":"canggu","name":"The Shady Shack","category":"cafe","description":"A long-running vegetarian and vegan cafe in a garden beside rice fields, opened in 2016 by the Betelnut founders. Nomad guides call it the quiet option with usable Wi-Fi (around 40 Mbps reported) but limited power plugs, so garden-side tables and a charged laptop are advised. There is no air-conditioning, and it gets busy around brunch.","address":"Jl. Tanah Barak No.57, Canggu, Kec. Kuta Utara, Kabupaten Badung, Bali 80351","lat":-8.65016,"lng":115.13367,"website":"https://www.theshadyshackbali.com/","phone":"+62 812 3611 6466","opening_hours":"Mo-Su 08:00-22:00","hours_source":"website","access":"open","access_note":"Walk-in customers; reservations are available. Arrive before the brunch rush for a calm seat; outlets are scarce.","coord_precision":"street"},
{"slug":"two-face-coffee-brunch-canggu","city":"canggu","name":"Two Face Coffee & Brunch","category":"cafe","description":"A photogenic brunch and coffee cafe with indoor and rooftop seating on Munduk Catu. Directories report free Wi-Fi, a decent number of plugs and varied seating. It can get lively, and road noise reaches some outdoor tables, so it suits lighter work sessions in the morning and early afternoon.","address":"Jl. Munduk Catu No.9, Canggu, Kec. Kuta Utara, Kabupaten Badung, Bali 80351","lat":-8.65364,"lng":115.13043,"website":"https://www.twofacebali.com/two-face-canggu","phone":"+62 812-3902-8952","opening_hours":"Mo-Su 07:30-15:30","hours_source":"website","access":"open","access_note":"Walk-in customers; buy food or drinks. Closes mid-afternoon per its own site.","coord_precision":"street"},
{"slug":"urban-bites-cafe-berawa-canggu","city":"canggu","name":"Urban Bites Cafe Berawa","category":"cafe","description":"A relaxed all-day cafe on Jl. Raya Semat in Berawa, from breakfast to dinner. Directories describe free, stable Wi-Fi, air-conditioning and many people working on laptops, with noise and crowding that can be mixed. Outlets are unconfirmed according to DeskBean.","address":"Jl. Raya Semat, Tibubeneng, Berawa, Canggu, Kabupaten Badung, Bali 80361","lat":-8.65093,"lng":115.14473,"website":"https://urbanbitesbali.com/canggu/","phone":"+62 877-8059-8994","opening_hours":"Mo-Su 07:00-23:00","hours_source":"website","access":"open","access_note":"Walk-in customers; buy food or drinks. Laptop-friendliness is documented by third-party directories only.","coord_precision":"street"},
{"slug":"zin-cafe-canggu","city":"canggu","name":"ZIN Cafe","category":"cafe","description":"Cafe attached to the ZIN Canggu resort, long known as a base for remote workers. The venue itself advertises a free co-working area (ZIN@Work), an air-conditioned focus room and fast Wi-Fi. Blogs add that the ground floor is for socialising while laptops go upstairs or to the back, and that the coworking hall has a minimum spend; one independent test of the Wi-Fi reportedly measured well below the advertised speed.","address":"Jl. Nelayan No.78, Canggu, Kuta Utara, Badung, Bali","lat":-8.65997,"lng":115.13353,"website":"https://zin.world/zin-cafe/","phone":"+62 811-3111-6646","outdoor_seating":"yes","access":"open","access_note":"Opening hours vary between sources (late closing is reported): check before going.","coord_precision":"venue"},
{"slug":"awan-connection-canggu","city":"canggu","name":"Awan Connection","category":"coworking","description":"Cafe-style coworking space behind Batu Bolong that the website presents as free to work from, with the cafe on site. Coworking hours on the site are shorter on weekdays after Wednesday and the space is closed on Sundays. Prices not published.","address":"Jl. Kayu Manis, Canggu, Kuta Utara, Badung 80351 (behind Pepito Batu Bolong)","lat":-8.64336,"lng":115.14291,"website":"https://www.awanconnection.com/","phone":"+6281220460620","opening_hours":"Mo,Tu 10:00-22:00; We-Sa 10:00-19:00; Su off","hours_source":"website","access":"open","access_note":"Cafe-based coworking; no pass needed according to the website.","coord_precision":"venue"},
{"slug":"bwork-canggu","city":"canggu","name":"BWork Canggu","category":"coworking","description":"Large coworking space plus cafe near Batu Bolong. Walk-in day passes are sold at the front desk and cannot be reserved ahead; each pass is valid for 24 hours from registration. Coworking is open around the clock and the cafe runs roughly 8:00 to 21:00. Closed on major Balinese holidays such as Nyepi. Prices (website, Nov 2026; VAT status not stated): day 299,000 IDR (199,000 for Indonesian ID holders), weekend day 200,000 IDR, non-peak weekly 800,000 IDR, 1-month unlimited 3,850,000 IDR (that plan covers both the Canggu and Uluwatu sites).","address":"Jl. Nelayan No.9C, Canggu, Kuta Utara, Badung 80361","lat":-8.65409,"lng":115.13284,"website":"https://bwork.id/membership/canggu/","opening_hours":"24/7","hours_source":"website","access":"registration","access_note":"Walk-in day pass registered with the host on arrival; no advance booking.","coord_precision":"venue"},
{"slug":"deos-coworking-canggu","city":"canggu","name":"DEOS Coworking","category":"coworking","description":"Small coworking space (about seven seats) in Canggu with 24/7 access via a smart lock, according to its website. The website shows two plan tiers with daily, weekly and monthly options. Prices (website, Nov 2026; VAT status not stated): day 200,000 IDR or 300,000 IDR depending on tier, week 900,000 or 1,200,000 IDR, month 1,800,000 or 2,400,000 IDR.","address":"Jl. Tanah Barak No.9B, Canggu, Kuta Utara, Badung 80351","lat":-8.64853,"lng":115.13596,"website":"https://deos.works/","phone":"+6282145503494","opening_hours":"24/7","hours_source":"website","access":"registration","access_note":"Plans purchased on the website; the two tiers are not clearly labelled, so confirm which day tier applies.","coord_precision":"venue"},
{"slug":"nebula-entrepreneur-space-canggu","city":"canggu","name":"Nebula Entrepreneur Space","category":"coworking","description":"Membership-based coworking space in Berawa with 24/7 member access, call booths, a recording studio and a spa area. The website sells monthly desks and offices and publishes no day pass; it markets the community to entrepreneurs with established sales. Prices (website, Nov 2026; VAT status not stated): dedicated floor desk 3,000,000 IDR per month.","address":"Jl. Raya Pantai Berawa, Gg. Jepun No.5, Tibubeneng, Kuta Utara, Badung 80361","lat":-8.64605,"lng":115.1533,"website":"https://nebula.training/","phone":"+6287790658914","access":"members","access_note":"Monthly memberships only (no day pass published); aimed at entrepreneurs, so confirm eligibility before visiting.","coord_precision":"venue"},
{"slug":"puco-rooftop-coworking-canggu","city":"canggu","name":"PUCO Rooftop Coworking","category":"coworking","description":"Rooftop coworking space in Tibubeneng on the northern side of Berawa. The website lists weekday access around the clock and shorter weekend hours. Day and 8-hour passes are sold to non-members. Prices (website, Nov 2026; VAT status not stated): day 200,000 IDR, 8 hours 150,000 IDR.","address":"Gg. Pratama No.1A, Tibubeneng, Kuta Utara, Badung 80361","lat":-8.63868,"lng":115.15188,"website":"https://pucorooftop.com/coworking-space/","phone":"+6285171088861","opening_hours":"Mo-Fr 00:00-24:00; Sa,Su 08:00-22:30","hours_source":"website","access":"registration","access_note":"Day pass sold to non-members; booking details not verified.","coord_precision":"venue"},
{"slug":"setter-canggu","city":"canggu","name":"SETTER Canggu","category":"coworking","description":"Modern office-style coworking building with open desks, private offices, Zoom rooms and an event space, advertised as open 24/7 with front-desk assistance from 07:00 to 23:00. SETTER also runs a Berawa Beach branch and an Ubud branch. Prices (website, Nov 2026; VAT status not stated): day 299,000 IDR with 24-hour access.","address":"Jl. Raya Semat No.1, Tibubeneng, Kuta Utara, Badung 80361","lat":-8.65226,"lng":115.14348,"website":"https://www.setter.work/","phone":"+628888323888","opening_hours":"24/7","hours_source":"website","access":"registration","access_note":"Day passes sold to non-members; offices are rented separately.","coord_precision":"venue"},
{"slug":"sokkool-coworking-canggu","city":"canggu","name":"SOKKOOL Coworking","category":"coworking","description":"Coworking floor inside a coliving building in Berawa, with 70+ desks, focus rooms, a podcast studio, gym and rooftop lounge. The website shows an 8:00 to 22:00 daily front desk and 24/7 access for members. Prices (website, Nov 2026; VAT status not stated): day 180,000 IDR, 50-hour flexi month 1,200,000 IDR, unlimited month 2,700,000 IDR.","address":"Jl. Pemelisan Agung No.7, Tibubeneng, Kuta Utara, Badung 80361","lat":-8.65956,"lng":115.13788,"website":"https://sokkool.com/coworking","phone":"+6281139619394","opening_hours":"Mo-Su 08:00-22:00","hours_source":"website","access":"registration","access_note":"Day pass sold online; coliving residents are a separate product.","coord_precision":"venue"},
{"slug":"tropical-nomad-coworking-canggu","city":"canggu","name":"Tropical Nomad Coworking","category":"coworking","description":"Coworking space with coliving rooms on a quiet lane in central Canggu. Members can come in 24 hours a day, while the front desk is staffed on shorter hours. Prices (website, Nov 2026; VAT status not stated): day pass 230,000 IDR (midnight to midnight).","address":"Jl. Subak Canggu No.2, Canggu, Kuta Utara, Badung 80361","lat":-8.65266,"lng":115.138,"website":"https://tropicalnomad.id/","phone":"+6281246926929","opening_hours":"Mo-Fr 07:00-21:00; Sa,Su 07:00-17:00","hours_source":"website","access":"registration","access_note":"Hours shown are front-desk hours; registered members have 24h access.","coord_precision":"venue"},
{"slug":"anma-space-denpasar","city":"denpasar","name":"Anma Space","category":"cafe","description":"Cafe on Jl. Tukad Badung in Renon with a quirky interior, a photobooth and a menu from lattes to full meals. Third Desk (checked Oct 2026) lists laptops as welcome with Wi-Fi available and a quiet room, and awifiplace lists it among Denpasar's laptop-friendly cafes. Reviews say loud music can distract at times. Outlets were not recorded.","address":"Jl. Tukad Badung No. 226, Renon, Denpasar Selatan, Denpasar, Bali 80226","lat":-8.68636,"lng":115.23817,"access":"open","access_note":"Walk in. Opening hours differ between sources: check before going.","coord_precision":"venue"},
{"slug":"connect-time-space-denpasar","city":"denpasar","name":"Connect Time Space","category":"cafe","description":"Coffee shop on Jl. Tukad Badung in Renon that doubles as a work space, with a bookable meeting room and a quiet, homely interior. Reviewers describe clean desks, comfortable chairs and reliable internet, and mention slower food service. One January 2026 reviewer disliked vaping indoors.","address":"Jl. Tukad Badung No. 18B, Renon, Denpasar Selatan, Denpasar, Bali 80226","lat":-8.68026,"lng":115.23798,"opening_hours":"Mo-Su 08:00-23:00","hours_source":"listing","access":"open","access_note":"Walk-in cafe; no booking needed, and staff expect you to order food or drinks while you work.","coord_precision":"street"},
{"slug":"dopa-renon-denpasar","city":"denpasar","name":"DOPA Renon","category":"cafe","description":"Cafe near the Renon government offices with spacious indoor and outdoor seating, specialty coffee and pastries. Laptop-friendly cafe directories describe Wi-Fi and plenty of power sockets, and its hours are consistently listed as 07:00-22:00 daily. Wi-Fi speed has not been independently verified.","address":"Jl. Tantular Kompleks Metro Futsal No. 7, Dangin Puri Klod, Denpasar Timur, Denpasar, Bali 80234","lat":-8.67031,"lng":115.22805,"opening_hours":"Mo-Su 07:00-22:00","hours_source":"listing","outdoor_seating":"yes","access":"open","access_note":"Walk in. Listings agree on 07:00-22:00 daily.","coord_precision":"venue"},
{"slug":"manos-cafe-renon-denpasar","city":"denpasar","name":"Manos Cafe Renon","category":"cafe","description":"Cafe in a Renon side street, picked by two remote-work cafe guides for Denpasar as a place to work on a laptop. Directories give its street address and opening hours, but Wi-Fi and socket details are not documented.","address":"Jl. Tukad Badung IIA No. 21B, Renon, Denpasar Selatan, Denpasar, Bali","lat":-8.67918,"lng":115.23724,"opening_hours":"Mo-Su 09:00-22:00","hours_source":"listing","access":"open","access_note":"Walk-in cafe; no booking needed, and staff expect you to order food or drinks while you work.","coord_precision":"street"},
{"slug":"ruang-santay-coffee-space-denpasar","city":"denpasar","name":"Ruang Santay Coffee & Space","category":"cafe","description":"Cafe and dessert shop on Jl. Tukad Balian in Renon with an air-conditioned room, street-facing outdoor seating and a meeting room that can be booked. Reviews on Wi-Fi are mixed: some call it fast, others found it too slow for productive work, and the room can be snug.","address":"Jl. Tukad Balian No. 164, Renon, Denpasar Selatan, Denpasar, Bali 80226","lat":-8.696499,"lng":115.242223,"phone":"+62 858-0050-8219","opening_hours":"Mo-Su 07:00-24:00","hours_source":"listing","access":"open","access_note":"Walk-in cafe; no booking needed, and staff expect you to order food or drinks while you work.","coord_precision":"street"},
{"slug":"traya-cafe-renon-denpasar","city":"denpasar","name":"Traya Cafe Renon","category":"cafe","description":"Quiet cafe in Renon with indoor and outdoor seating, big parking area and a socket at nearly every table. A 2026 NusaBali feature describes most tables occupied by laptop users at midday and a calm atmosphere, and awifiplace lists it among Denpasar's laptop-friendly cafes. The same article gives 08:00-22:00 daily.","address":"Jl. Tukad Citarum LC1 No. 2A, Renon, Denpasar Selatan, Denpasar, Bali","lat":-8.679518,"lng":115.234923,"outdoor_seating":"yes","access":"open","access_note":"Walk in; ordering is at the counter. Opening hours differ between sources: check before going.","coord_precision":"venue"},
{"slug":"regus-renon-landmark-denpasar","city":"denpasar","name":"Regus Renon Landmark","category":"coworking","description":"Serviced-office building near Bajra Sandhi and the Renon government district, run in partnership with Regus, offering coworking desks, day coworking, meeting rooms and virtual offices. The building site lists weekday and Saturday office hours, high-speed Wi-Fi, parking and a rooftop. Prices (website, Nov 2026, excl. VAT): day coworking from 250,000 IDR on the Regus Kesiman page, while another Regus page shows 290,000 IDR.","address":"Jl. Prof. Moh. Yamin No. 7, Sumerta Kelod, Denpasar Timur, Denpasar, Bali 80226","lat":-8.67205,"lng":115.2381,"website":"https://www.renonlandmark.com/en/","phone":"+62 361 4458157","opening_hours":"Mo-Fr 08:00-17:30; Sa 08:00-15:30","hours_source":"website","access":"registration","access_note":"Book through Regus or the Renon Landmark team; day-pass users get standard office hours only.","coord_precision":"street"},
{"slug":"perpustakaan-daerah-provinsi-bali-denpasar","city":"denpasar","name":"Perpustakaan Daerah Provinsi Bali","category":"library","description":"Bali provincial library, moved in 2022 from Renon to Jl. Tukad Batanghari XIV in Panjer. A 2026 NusaBali article says visitors come to read, do assignments, study in groups and join online meetings using the library Wi-Fi, and that the collection ranges from children's books to academic references. The adult reading area is on an upper floor.","address":"Jl. Tukad Batanghari XIV No. 2, Panjer / Dauh Puri Klod, Denpasar Selatan, Denpasar, Bali 80225","lat":-8.68588,"lng":115.22899,"access":"open","access_note":"Reported closed Saturday and Sunday. Weekday hours differ between sources (about 08:00-15:15 or 16:00 Mon-Thu, 08:00-12:45 or 14:00 Fri): check before going. A membership card is needed to borrow books.","coord_precision":"venue"},
{"slug":"perpustakaan-umum-kota-denpasar","city":"denpasar","name":"Perpustakaan Umum Kota Denpasar","category":"library","description":"Municipal public library run by the Denpasar library and archives office on Jl. Surapati, near Lapangan Puputan Badung. The office's FAQ lists on-site reading, free Wi-Fi, free computers and a children's library; detik reports reading and study tables plus lockers. Borrowing needs a Denpasar ID card.","address":"Jl. Surapati No. 4, Denpasar","lat":-8.65632,"lng":115.21934,"website":"https://arsip.denpasarkota.go.id/","phone":"+62 361 237426","access":"open","access_note":"On-site reading is a listed service. Official pages disagree on hours (about 08:00-14:00 or 15:00 Mon-Thu, 08:00-12:00 or 12:30 Fri), so check before going.","coord_precision":"venue"},
{"slug":"balagan-ericeira-cafe-deli-ericeira","city":"ericeira","name":"Balagan Ericeira (Café & Deli)","category":"cafe","description":"Beachfront Eastern Mediterranean café-deli, restaurant and bar in the former Edifício Virtual at Praia do Sul, with a terrace over the ocean. Local guides call it the unofficial remote-worker canteen, and one reviewer mentions a designated coworking table.","address":"Praia do Sul, 2655-306 Ericeira","lat":38.95763,"lng":-9.41552,"website":"https://www.balaganfood.com/","phone":"+351 913 362 452","opening_hours":"Mo-Su 10:00-18:00","hours_source":"website","outdoor_seating":"yes","access":"open","access_note":"Hours are for the Deli & Café on the venue's contact page; the restaurant and bar keep separate hours. The coordinate marks Praia do Sul beach next to the building.","coord_precision":"venue"},
{"slug":"boardriders-ericeira-quiksilver-ericeira","city":"ericeira","name":"Boardriders Ericeira (Quiksilver)","category":"cafe","description":"Surf and skate shop with a café, terrace and skate bowl at São Sebastião. Guides and travel bloggers describe spacious indoor seating that suits a laptop for a few hours, and the café is listed with free Wi-Fi.","address":"Largo São Sebastião 36A, 2655-319 Ericeira","lat":38.97648,"lng":-9.41876,"website":"https://www.boardriders.com/en/gb/stores/shop/1007955/","phone":"+351 261 867 046","opening_hours":"Mo-Su 10:00-21:00","hours_source":"website","wheelchair":"yes","outdoor_seating":"yes","access":"open","access_note":"Hours are from the brand's store page; some listings give a 20:00 close. Buy a drink to sit; indoor space can be limited when it rains.","coord_precision":"venue"},
{"slug":"break-point-ericeira","city":"ericeira","name":"Break Point Ericeira","category":"cafe","description":"Private tennis club with a café, bar and restaurant in the Moinhos do Mar development, with several large tables indoors and outdoors overlooking the courts. Guides say you can work if you order food or drinks, and Wednesday is a 'cowork day' with a 15 EUR lunch-plus-tennis deal.","address":"Urbanização Moinhos do Mar, Rua 6, Lote C, 2655-319 Ericeira","lat":38.97469,"lng":-9.41835,"website":"http://breakpointclub.com/","outdoor_seating":"yes","access":"open","access_note":"Work space is free with bar or restaurant consumption per the Ericeira Mag guide; hours differ between sources, so none are listed. The coordinate comes from the venue's own map link.","coord_precision":"venue"},
{"slug":"dear-rose-cafe-ericeira","city":"ericeira","name":"Dear Rose Café","category":"cafe","description":"Small, art-filled specialty café in the centre of Ericeira with Wi-Fi, a small terrace and a plant-based-leaning brunch menu. Listings tag it laptop-friendly, but with only a few tables it works best for a short session.","address":"Rua de Santo António 12A, 2655-360 Ericeira","lat":38.96395,"lng":-9.41757,"phone":"+351 913 879 407","outdoor_seating":"yes","access":"open","access_note":"Order at the counter; closed Mondays according to several listings, but opening times vary slightly between sources so none are listed.","coord_precision":"venue"},
{"slug":"hurley-surf-club-ericeira","city":"ericeira","name":"Hurley Surf Club Ericeira","category":"cafe","description":"Surf shop, specialty café and bakery near Praça dos Navegantes that has two tables set aside for laptop work. Local guides and reviewers describe a relaxed mix of remote workers and surfers, and advise ordering regularly if you stay for a couple of hours.","address":"Calçada da Baleia 18B, 2655-238 Ericeira","lat":38.96222,"lng":-9.41624,"website":"https://hurleyericeira.com/","phone":"+351 926 072 027","outdoor_seating":"yes","access":"open","access_note":"Walk in and buy food or drinks; no time limit is published. Hours differ between the venue site and third-party guides, so they are not listed.","coord_precision":"venue"},
{"slug":"sunset-bamboo-ericeira","city":"ericeira","name":"Sunset Bamboo","category":"cafe","description":"Laid-back café and juice bar just off Jogo da Bola square with comfy chairs, a sofa and outdoor tables. Local blogs and guides describe it as welcoming to laptops, and listings mention free Wi-Fi. It is cash-oriented according to some listings.","address":"Travessa do Jogo da Bola 3, 2655-297 Ericeira","lat":38.96316,"lng":-9.4166,"outdoor_seating":"yes","access":"open","access_note":"Order food or drinks to settle in; opening hours and the phone number differ between listings, so they are not given here.","coord_precision":"venue"},
{"slug":"the-capsule-ericeira","city":"ericeira","name":"The Capsule","category":"cafe","description":"Specialty coffee shop that roasts its own beans, in the old town. Listings describe fast Wi-Fi and sockets at most indoor tables and regulars working on laptops. Food is mostly cakes and sandwiches, so it suits a shorter session.","address":"Rua da Fonte do Cabo 54A, 2655-344 Ericeira","lat":38.96315,"lng":-9.41672,"website":"https://capsule.cafe/","opening_hours":"Mo-Su 09:00-19:00","hours_source":"website","outdoor_seating":"yes","access":"open","access_note":"Buy a drink or cake to sit; the kitchen closes at 18:30 per the venue's site.","coord_precision":"venue"},
{"slug":"the-organic-way-ericeira","city":"ericeira","name":"The Organic Way","category":"cafe","description":"Organic grocery, café and cantina, yoga studio and sauna under one roof in Ericeira, with a dedicated cowork area. The venue says the cowork area is free to use for as long as needed with food and drinks served at the table, while working from the café itself costs a 15 EUR day fee including one drink.","address":"Rua do Mercado 20, 2655-331 Ericeira","lat":38.96518,"lng":-9.41618,"website":"https://www.theorganicway.club/","phone":"+351 938 424 102","access":"open","access_note":"No membership needed to drop in and work; the venue's own FAQ describes the free cowork area and the 15 EUR café day fee. Opening hours are not listed because sources differ.","coord_precision":"venue"},
{"slug":"tiger-chick-ericeira","city":"ericeira","name":"Tiger & Chick","category":"cafe","description":"Small specialty coffee shop in central Ericeira serving hand-brew coffee, matcha, cakes and baked goods. Third-party guides list free Wi-Fi, power outlets and a quiet atmosphere, but with only a few tables it fits short work sessions.","address":"Rua do Caldeira 37A, 2655-249 Ericeira","lat":38.96371,"lng":-9.41686,"website":"https://tigerandchick.com/","opening_hours":"Mo-Su 09:30-16:00","hours_source":"website","outdoor_seating":"yes","access":"open","access_note":"The venue's site says open daily 9:30-16:00; a third-party listing says Sundays are closed, so check before going on a Sunday.","coord_precision":"venue"},
{"slug":"coastal-cowork-collective-ericeira","city":"ericeira","name":"Coastal Cowork Collective","category":"coworking","description":"Design-led coworking in the centre of Ericeira, a few minutes from Praia Norte, with communal tables, lounge zones, four small soundproofed meeting rooms and a kitchen. Specialty coffee and tea are included with every pass. Prices (website, Nov 2026, VAT status not stated): day 17 EUR, week 79 EUR, 10 days/month 135 EUR, month 196 EUR, 3 months 536 EUR.","address":"Rua de São Félix 12E, 2655-362 Ericeira","lat":38.96731,"lng":-9.4178,"website":"https://www.coastal-collective.cc/","day_pass_price_cents":1700,"wheelchair":"yes","outdoor_seating":"yes","access":"open","access_note":"Day pass ('beach break') is sold on the website; weekly and longer plans include 24/7 access. The street address comes from third-party listings because the venue's own page does not print it.","coord_precision":"venue"},
{"slug":"ericeira-business-factory-coworking-ericeira","city":"ericeira","name":"Ericeira Business Factory (Coworking)","category":"coworking","description":"Municipal startup incubator in the former primary school in Ericeira's centre, which also rents coworking desks to established freelancers and small businesses. Contracts run for at least six months and include meeting-room hours, mail reception and parking. Prices not published.","address":"Rua Prudêncio Franco da Trindade 4, Ericeira","lat":38.96367,"lng":-9.41651,"website":"https://www.businessfactory.pt/","phone":"+351 261 101 912","access":"application","access_note":"Admission is by application form on the website and a meeting with the incubator; the coworking service is a contract of at least 6 months, with a separate short-term hot-desk option of up to 15 days for entrepreneurs.","coord_precision":"venue"},
{"slug":"kelp-coworking-space-ericeira","city":"ericeira","name":"Kelp Coworking Space Ericeira","category":"coworking","description":"Independent coworking in Ericeira's old town, a short walk from Praia Norte, running since 2020. It has a communal table, five bookable phone booths, a kitchen and tea/coffee included with the pass. Prices (website, Nov 2026, VAT status not stated): day 17 EUR, 12 days 145 EUR, week 79 EUR, own desk 199 EUR/month.","address":"Rua de São Félix 12, 2655-246 Ericeira","lat":38.96731,"lng":-9.4178,"website":"https://kelpcowork.com/","phone":"+44 7793 077849","day_pass_price_cents":1700,"wheelchair":"yes","access":"open","access_note":"Day passes are booked online by date; members get 24/7 access and reception is staffed on weekdays 9:00-12:00 per the website.","coord_precision":"venue"},
{"slug":"lapoint-surf-camp-cowork-ericeira","city":"ericeira","name":"Lapoint Surf Camp Cowork","category":"coworking","description":"Coworking area inside the Lapoint surf camp above Foz do Lizandro, with two call booths, a meeting room and a quiet setting away from the town centre. Camp guests on the Work & Surf package use it 24/7, and a 2025 local guide also lists day, week and month passes. Prices not published on the venue pages opened.","address":"Rua das Curveiras s/n, 2655-077 Carvoeira (Foz do Lizandro), Ericeira","lat":38.94585,"lng":-9.41115,"website":"https://www.lapointcamps.com/surfcamp/portugal/ericeira/work-and-surf/","phone":"+351 911 798 741","access":"open","access_note":"Public day, week and month passes are reported by the Ericeira Mag guide (March 2025); confirm availability with the camp before visiting. Hours are not listed here because sources disagree on public access.","coord_precision":"venue"},
{"slug":"mother-cowork-ericeira","city":"ericeira","name":"Mother Cowork","category":"coworking","description":"Hybrid space a few metres from Jogo da Bola square: a café on the ground floor and a coworking area downstairs, with a meeting room and screens for connecting laptops. Coffee is included with the day pass and a half-day pass exists. Prices not published by the venue; third-party guides disagree on the details.","address":"Travessa do Jogo da Bola 1, 2655-297 Ericeira","lat":38.96316,"lng":-9.4166,"access":"open","access_note":"Day and half-day passes are reported by third-party guides only; confirm price and opening times locally.","coord_precision":"venue"},
{"slug":"surf-work-ericeira","city":"ericeira","name":"Surf & Work","category":"coworking","description":"Coworking space that opened in January 2026 on Praça dos Navegantes, with desks and group tables, call booths, a meeting room, an eating area and showers/changing room for surfers. Drop-in passes come in 2, 4 and 6-hour and full-day versions with coffee or tea included. Prices (website, Nov 2026): drop-in from 5.49 EUR for 2 hours; full-day price not published on the page.","address":"Praça dos Navegantes 2, Loja 10, 2655-320 Ericeira","lat":38.96143,"lng":-9.4165,"website":"https://www.surf-and-work.com/","access":"open","access_note":"Pre-paid drop-in cards and monthly passes are bought online; Croissant members are accepted subject to seat availability.","coord_precision":"venue"},
{"slug":"biblioteca-municipal-da-ericeira","city":"ericeira","name":"Biblioteca Municipal da Ericeira","category":"library","description":"Municipal library in the Casa de Cultura Jaime Lobo e Silva, the former casino building near Jogo da Bola. It has an open first-floor room with small tables and a reading room with larger tables; a local guide reports free Wi-Fi in both and sockets only in the reading room.","address":"Casa de Cultura Jaime Lobo e Silva, Rua Mendes Leal, 2655-305 Ericeira","lat":38.96319,"lng":-9.41777,"website":"https://www.cm-mafra.pt/pages/1034?poi_id=57","phone":"+351 261 860 553","opening_hours":"Tu-Sa 10:00-13:00,14:00-19:00","hours_source":"website","wheelchair":"yes","access":"open","access_note":"Free public access; silence is expected. Wi-Fi and socket details are from a third-party guide (March 2025); the municipality states the building has access for people with reduced mobility.","coord_precision":"venue"},
{"slug":"c-cafe-jimbaran","city":"jimbaran","name":"C-Café Jimbaran","category":"cafe","description":"Small air-conditioned cafe on Jl. Uluwatu II with an indoor room and a few outdoor seats, serving coffee and sandwiches. Third Desk (checked Oct 2026) lists laptops as welcome with Wi-Fi available, and DeskBean reports reliable Wi-Fi and plenty of outlets, though it can get noisy. The cafe is compact.","address":"Jl. Uluwatu II No. 54, Jimbaran, Kuta Selatan, Badung, Bali 80361","lat":-8.78236,"lng":115.16717,"access":"open","access_note":"Walk in. Third Desk shows Sunday closed, but hours were not confirmed by a second source: check before going.","coord_precision":"venue"},
{"slug":"colabo-cafe-jimbaran-hub-jimbaran","city":"jimbaran","name":"Colabo Cafe (Jimbaran Hub)","category":"cafe","description":"Cafe inside the Jimbaran Hub community complex, next to a playground and skatepark, which describes itself as a space for remote workers by day and jazz dinners at night. The operator's Jimbaran Hub site advertises high-speed internet, power outlets and indoor plus semi-garden seating. Wi-Fi quality has not been independently verified.","address":"Jimbaran Hub, Jl. Karang Mas, Jimbaran, Kuta Selatan, Badung, Bali 80361","lat":-8.793319,"lng":115.150225,"website":"https://cafe.colabo.id/","outdoor_seating":"yes","access":"open","access_note":"Walk in. Opening hours were not found in the sources opened: check before going.","coord_precision":"venue"},
{"slug":"nectar-specialty-coffee-viennoiserie-jimbaran","city":"jimbaran","name":"Nectar Specialty Coffee & Viennoiserie","category":"cafe","description":"Bakery cafe in Ungasan with a minimalist, European-style room, French-style croissants baked daily and breakfast-to-rice menu. Directories list it as laptop-friendly, quiet and air-conditioned with Wi-Fi. Opening days vary between sources, so confirm before a long trip.","address":"Jl. Merak III No. 3, Ungasan, Kuta Selatan, Badung, Bali 80361","lat":-8.81788,"lng":115.1703,"phone":"+62 811 3865 828","access":"open","access_note":"Walk-in cafe; no booking needed, order food or drinks. Hours conflict: the bakery's own page lists Wed-Mon 08:00-17:00 with Tuesday closed, while directories show daily 08:30-17:00; check before going.","coord_precision":"street"},
{"slug":"simplii-coffee-jimbaran","city":"jimbaran","name":"simplii.coffee","category":"cafe","description":"Specialty coffee shop in the Pasraman Unud housing area near the Udayana campus, with espresso, filter, matcha and light meals. DeskBean and Third Desk both report fast Wi-Fi, sockets and air-conditioning. Third Desk also notes it can be loud, with a DJ at times.","address":"Jl. Perum Pasraman Unud No. B98, Jimbaran, Kuta Selatan, Badung, Bali 80361","lat":-8.79152,"lng":115.16928,"phone":"+62 812-3786-0272","opening_hours":"Mo-Su 08:00-22:00","hours_source":"listing","access":"open","access_note":"Walk-in cafe; no booking needed, and staff expect you to order food or drinks while you work.","coord_precision":"street"},
{"slug":"teraskota-coffee-eatery-jimbaran","city":"jimbaran","name":"Teraskota Coffee & Eatery Jimbaran","category":"cafe","description":"Casual coffee and eatery beside Hotel Paragon on the Udayana campus road, with indoor and garden seating and a kids' corner. Reviewers say Wi-Fi is issued after ordering and that there are enough sockets for a laptop session. Reviewers find it better for a few hours than for a full day.","address":"Jl. Raya Kampus Unud (next to Hotel Paragon), Jimbaran, Kuta Selatan, Badung, Bali 80361","lat":-8.78481,"lng":115.17796,"website":"https://teraskota-bali.com/","phone":"+62 857-9242-0983","access":"open","access_note":"Walk-in cafe; no booking needed, and staff expect you to order food or drinks while you work.","coord_precision":"street"},
{"slug":"bukithub-jimbaran","city":"jimbaran","name":"BukitHub","category":"coworking","description":"Coworking space in Ungasan with open desks, coffee and printing included in the day pass. The reception desk keeps shorter hours than the 24/7 keycard access for weekly and monthly members. The website lists a day pass at IDR 150,000 (first visit 50% off) and a week at IDR 600,000.","address":"Jl. Pura Batu Pageh No.177AA, Ungasan, Kuta Selatan, Badung 80361","lat":-8.8199,"lng":115.16111,"website":"https://bukithub.com/","phone":"+6281138104100","access":"registration","access_note":"Reception Mon-Sat 10:00-21:00, Sun 11:00-15:00; weekly/monthly members get 24/7 access.","coord_precision":"venue"},
{"slug":"hedonist-space-coworking-jimbaran","city":"jimbaran","name":"Hedonist Space Coworking","category":"coworking","description":"Restaurant and lounge in Ungasan with a coworking area that stays open 24 hours for workspace users. The site sells meeting rooms and phone booths by the hour and dedicated desks by the month, while day passes are quoted on request. Prices not published.","address":"Jl. Raya Uluwatu No.72, Ungasan, Kuta Selatan, Badung 80361","lat":-8.82044,"lng":115.15061,"website":"https://hedonist-space.com/","phone":"+6287842740470","opening_hours":"24/7","hours_source":"website","access":"registration","access_note":"Day pass available on request; coordinate taken from the website's Google Maps pin.","coord_precision":"venue"},
{"slug":"monday-coworking-and-coffee-jimbaran","city":"jimbaran","name":"Monday Coworking and Coffee","category":"coworking","description":"Coworking space and coffee shop in Ungasan with indoor and outdoor work areas, phone booths and bookable meeting rooms. The coffee shop keeps shorter hours than the coworking area. The website lists a day pass at IDR 225,000 and a 4-hour pass at IDR 125,000.","address":"Jl. Toya Ning II, Ungasan, Kuta Selatan, Badung 80361","lat":-8.8245,"lng":115.14427,"website":"https://mondaybali.com/coworking","phone":"+6285979244883","opening_hours":"Mo-Sa 08:00-23:00","hours_source":"website","access":"registration","access_note":"Coffee shop open Mon-Sat 07:00-19:30. Coordinate from a third-party place record (street not in OSM).","coord_precision":"venue"},
{"slug":"regus-benoa-square-jimbaran","city":"jimbaran","name":"Regus Benoa Square","category":"coworking","description":"Regus-operated business centre on the 2nd floor of the Benoa Square building on the Bypass, with a business lounge, coffee bar and parking. Day coworking is bookable online, and members get 24/7 access; day-pass users use standard office hours. Prices (website, Nov 2026): day coworking from 190,000 IDR, meeting room from 250,000 IDR per hour.","address":"2nd Floor, Benoa Square Building, Jl. Bypass Ngurah Rai No. 21A, Kedonganan, Kuta, Badung, Bali 80361","lat":-8.761465,"lng":115.179286,"website":"https://www.regus.com/en/id/perarudan","opening_hours":"Mo-Fr 08:30-18:00","hours_source":"listing","access":"registration","access_note":"Book a day desk online through Regus or a partner site; it is a corporate centre, so expect a reception check-in.","coord_precision":"street"},
{"slug":"perpustakaan-universitas-udayana-jimbaran","city":"jimbaran","name":"Perpustakaan Universitas Udayana","category":"library","description":"Main library of Udayana University on the Bukit Jimbaran campus, with reading areas, discussion rooms, visitor lockers and an online catalogue. The university's pages list Monday-Friday service hours; a BaleBengong article says the public may read on site for free while borrowing is for university members. Facilities are aimed at students and researchers, so expect an academic atmosphere.","address":"Jl. Raya Kampus Unud, Bukit Jimbaran, Kuta Selatan, Badung, Bali 80361","lat":-8.79473,"lng":115.1739,"website":"https://e-perpus.unud.ac.id/","opening_hours":"Mo-Fr 08:00-19:00","hours_source":"website","access":"open","access_note":"Reading on site is reported open to the public; borrowing is for Udayana members only. Closed Saturdays, Sundays and public holidays per the university page.","coord_precision":"venue"},
{"slug":"crumb-coaster-kuta","city":"kuta","name":"Crumb & Coaster","category":"cafe","description":"Long-running all-day cafe tucked down a narrow lane in Kuta, a short walk from the beach, with outdoor seating and an air-conditioned indoor room. Honeycombers recommends the air-conditioned room for working, and DeskBean lists Wi-Fi and outlets, noting it gets busy around brunch.","address":"Jl. Benesari No. 2E, Kuta, Badung, Bali 80361","lat":-8.71719,"lng":115.17242,"opening_hours":"Mo-Su 07:30-23:00","hours_source":"listing","outdoor_seating":"yes","access":"open","access_note":"Walk in; scooter parking is available but the lane is narrow. Best before the brunch rush.","coord_precision":"venue"},
{"slug":"gowork-park23-kuta","city":"kuta","name":"GoWork Park23","category":"coworking","description":"Branch of the Indonesian GoWork chain on the third floor of the Park23 creative complex near the airport. Weekday office hours are published on the location page. Prices (website, Nov 2026, from, plus VAT): from 180,000 IDR per day plus VAT.","address":"Park23 Creative Hub, 3rd floor, Jl. Kediri, Tuban, Kuta, Badung 80361","lat":-8.73689,"lng":115.175713,"website":"https://go-work.com/locations/bali/park-23","opening_hours":"Mo-Fr 09:00-18:00","hours_source":"website","access":"registration","access_note":"Day pass booked through GoWork; street-level coordinate (exact building not geocoded).","coord_precision":"venue"},
{"slug":"art-coffe-by-earth-espice-legian","city":"legian","name":"Art Coffe by Earth Espice","category":"cafe","description":"Air-conditioned specialty coffee shop on Jl. Legian that serves coffee, matcha, breakfast and desserts from early morning to late evening. Work-friendly listings describe quiet seating and good Wi-Fi, but note that power sockets are scarce, so bring a charged laptop.","address":"Jl. Raya Legian No. 350, Legian, Kuta, Badung, Bali 80361","lat":-8.71209,"lng":115.173,"website":"https://artcoffe.id/","phone":"+62 878-7693-8680","opening_hours":"Mo-Su 07:30-23:00","hours_source":"website","access":"open","access_note":"Walk-in cafe; no booking needed, and staff expect you to order food or drinks while you work.","coord_precision":"venue"},
{"slug":"drift-cafe-legian","city":"legian","name":"Drift Cafe","category":"cafe","description":"All-day cafe on Jl. Sri Rama a few minutes' walk from Legian Beach, with a retro-minimalist interior and a focus on coffee. DeskBean reports fast Wi-Fi and plentiful outlets but no air-conditioning (ceiling fans only), and an Indonesian travel site lists it as a place to work on a laptop. Evenings shift to a cafe-bar menu.","address":"Jl. Sri Rama No. 41, Legian, Kuta, Badung, Bali 80361","lat":-8.70577,"lng":115.17545,"phone":"+62 822-3084-9512","opening_hours":"Mo-Su 06:00-22:00","hours_source":"listing","access":"open","access_note":"Walk in. Listings agree on 06:00-22:00 daily; no air-conditioning, so mornings are cooler for work.","coord_precision":"venue"},
{"slug":"fork-bali-legian","city":"legian","name":"FORK Bali","category":"cafe","description":"Bakery and grill-style cafe on Jl. Melasti that runs around the clock, which is unusual for Bali and handy for early flights or late-night work. The venue's own site advertises 24-hour opening and a Honeycombers 2026 guide covers it as a place to work.","address":"Jl. Melasti No. 1, Legian, Kuta, Badung, Bali 80361","lat":-8.70891,"lng":115.16819,"website":"https://wethefork247.com/","phone":"+62 882-9460-5373","opening_hours":"24/7","hours_source":"website","access":"open","access_note":"Walk-in cafe; no booking needed, and staff expect you to order food or drinks while you work.","coord_precision":"street"},
{"slug":"pico-coffee-legian","city":"legian","name":"Pico Coffee","category":"cafe","description":"Spacious converted-warehouse style cafe on Jl. Nakula with an air-conditioned area and a separate room that DeskBean describes as laptop-friendly, with free Wi-Fi and outlets at indoor tables. BaliFolio visitor reviews mention it as comfortable for working from the cafe. Opening hours could not be confirmed from the sources opened.","address":"Jl. Nakula No. 808, Legian, Kuta, Badung, Bali 80361","lat":-8.69814,"lng":115.17399,"access":"open","access_note":"Walk in. Opening hours were not confirmed: check before going.","coord_precision":"venue"},
{"slug":"prince-coffee-kitchen-legian","city":"legian","name":"Prince Coffee & Kitchen Legian","category":"cafe","description":"Cafe and kitchen on Jl. Kresna in central Legian, listed by several laptop-friendly cafe directories. The menu covers coffee plus breakfast and all-day meals, so it works for a long sit-down session.","address":"Jl. Kresna No. 3, Legian, Kuta, Badung, Bali 80361","lat":-8.69833,"lng":115.17266,"opening_hours":"Mo-Su 07:00-22:00","hours_source":"listing","access":"open","access_note":"Walk-in cafe; no booking needed, and staff expect you to order food or drinks while you work.","coord_precision":"street"},
{"slug":"republic-88-coffee-and-eatery-legian","city":"legian","name":"Republic 88 Coffee and Eatery","category":"cafe","description":"Casual coffee shop and eatery on Jl. Legian that opens early and shows up on several nomad directories as a laptop spot. It serves coffee and a full cafe menu, which makes it easy to stay through a meal.","address":"Jl. Raya Legian No. 355, Legian, Kuta, Badung, Bali 80361","lat":-8.71072,"lng":115.17244,"opening_hours":"Mo-Su 06:00-22:00","hours_source":"listing","access":"open","access_note":"Walk-in cafe; no booking needed, and staff expect you to order food or drinks while you work.","coord_precision":"venue"},
{"slug":"bali-bustle-coworking-kuta-legian","city":"legian","name":"Bali Bustle Coworking Kuta","category":"coworking","description":"Coworking space attached to the Bali Bustle coliving residence on Jl. Dewi Sri II, on the Legian-Kuta border. The company site advertises round-the-clock access. Prices (website, Nov 2026): day 150,000 IDR, week 700,000 IDR, month 2,000,000 IDR.","address":"Jl. Dewi Sri II No.23, Legian, Kuta, Badung 80361","lat":-8.70254,"lng":115.17768,"website":"https://balibustle.com/coworking-space-bali","opening_hours":"24/7","hours_source":"website","access":"registration","access_note":"Day pass sold on the website; Bali Bustle also operates other branches not listed here.","coord_precision":"venue"},
{"slug":"hub-bali-coworking-legian","city":"legian","name":"Hub Bali Coworking Legian","category":"coworking","description":"Affordable coworking inside a residence complex in Legian, with registered members able to access it around the clock. The same company runs a second hub in Nusa Dua. Prices (website, Nov 2026, incl. tax and service as published): day 125,000 IDR, week 600,000 IDR, month 1,200,000 IDR.","address":"Sara Residence, Jl. Nakula No.9, Legian, Kuta, Badung 80361","lat":-8.69896,"lng":115.17505,"website":"https://hubbali.co/","phone":"+6282210131702","access":"registration","access_note":"Day pass for non-members; 24/7 access for members.","coord_precision":"venue"},
{"slug":"nuts-coworking-social-space-lourinha","city":"lourinha","name":"NUTS Coworking & Social Space","category":"coworking","description":"Open-space coworking in central Lourinhã, a few minutes from the sea, with shared and fixed desks, a meeting room for six, a call booth, lockers, a relax zone and a small kitchen with coffee and tea. Prices (website, Nov 2026): day 12 EUR (half day 8 EUR, hourly 4 EUR), 5-day pass 50 EUR, flex desk 95 EUR/month, fixed desk 125 EUR/month.","address":"Rua Heróis do Ultramar 5, 2530-155 Lourinhã","lat":39.24187,"lng":-9.31364,"website":"https://gonuts.pt/","phone":"+351 261 412 143","opening_hours":"Mo-Fr 09:00-19:00","hours_source":"website","day_pass_price_cents":1200,"access":"open","access_note":"Daily plan needs a prior booking and confirmation of seat availability. The coordinate is on the same street (street-level), not building-level.","coord_precision":"venue"},
{"slug":"biblioteca-municipal-da-lourinha","city":"lourinha","name":"Biblioteca Municipal da Lourinhã","category":"library","description":"Municipal public library on Rua Miguel Bombarda in Lourinhã, with a public catalogue and borrowing for readers. It runs a reduced weekday timetable from July to September.","address":"Rua Miguel Bombarda 23, 2530-161 Lourinhã","lat":39.2417,"lng":-9.3112,"website":"https://portaldomunicipe.cm-lourinha.pt/2462/horarios-e-localizacao","phone":"+351 261 410 133","opening_hours":"Mo-Fr 10:00-17:30; Sa 10:00-16:00","hours_source":"website","access":"open","access_note":"Hours are from the municipality's portal; a parish website lists different hours, so check by phone. Wi-Fi and study seats are not stated. Summer (July-September): Mo-Fr 10:00-16:00, closed Saturday. Closed on public holidays.","coord_precision":"venue"},
{"slug":"coffeenosky-coffee-eatery-lovina","city":"lovina","name":"Coffeenosky Coffee & Eatery","category":"cafe","description":"Specialty coffee shop in Kalibukbuk that invites guests to work remotely, with views over the rice fields. Its own site advertises remote-work friendliness and a listing mentions high-speed Wi-Fi. A Feb 2026 TripAdvisor review says laptop users can occupy tables, so seats may be scarce. It reopened on 15 Aug 2026 after a renovation.","address":"Jl. Raya Singaraja-Seririt, Kalibukbuk, Lovina, Buleleng, Bali 81152, Indonesia","lat":-8.16155,"lng":115.02796,"website":"https://coffeenosky.wixsite.com/home","phone":"+62 821-4793-9996","access":"open","access_note":"Walk in; no booking needed. Order food or drinks to use a table. Reopened Aug 2026 after renovation; hours differ between the site and recent posts, so check before going.","coord_precision":"venue"},
{"slug":"cocoon-lovina-coworking-lovina","city":"lovina","name":"Cocoon Lovina Coworking","category":"coworking","description":"Coworking space at Lovina Arena in Anturan, described by a north Bali guide as Lovina's dedicated coworking space. It offers open workspaces, a private call/podcast room, a collaborative room and a coffee corner. Half-day and weekly passes are posted on its Instagram. Prices not published.","address":"Lovina Arena, R2QH+JPX, Anturan, Buleleng 81152","lat":-8.16092,"lng":115.02931,"website":"https://www.instagram.com/cocoon.lovina","phone":"+6282340143183","access":"registration","access_note":"Message or walk in; current prices and hours are posted on Instagram. No website.","coord_precision":"venue"},
{"slug":"bup-cowork-mafra","city":"mafra","name":"bUp Cowork","category":"coworking","description":"Coworking space in the centre of Mafra with defined desks, meeting rooms, a lounge and a kitchen. The desk plan on the website runs 9:00-18:00 with Wi-Fi. Prices (website, Nov 2026): desk 12 EUR (per day, as confirmed by a third-party listing); meeting rooms from 10 EUR/hour per that listing.","address":"Avenida Engenheiro Duarte Pacheco 3A, 2640-476 Mafra","lat":38.94029,"lng":-9.32909,"website":"https://bup.pt/coworking-mafra/","phone":"+351 261 819 620","opening_hours":"Mo-Fr 09:00-18:00","hours_source":"website","day_pass_price_cents":1200,"wheelchair":"yes","access":"open","access_note":"Contact the team by phone or email to book a desk; the weekday-only schedule is inferred from the 9:00-18:00 desk plan and the business listing.","coord_precision":"venue"},
{"slug":"mafra-business-factory-coworking-mafra","city":"mafra","name":"Mafra Business Factory (Coworking)","category":"coworking","description":"Mafra's municipal incubator, a sister site of the Ericeira Business Factory, offering coworking workstations to entrepreneurs with consolidated projects. Contracts run at least six months. Prices not published.","address":"Avenida 1º de Maio 1, Mafra","lat":38.93773,"lng":-9.33366,"website":"https://www.businessfactory.pt/","phone":"+351 261 024 870","access":"application","access_note":"Admission is by application form on the website; the coworking service is a contract of at least 6 months. The coordinate is street-level, not building-level.","coord_precision":"venue"},
{"slug":"biblioteca-municipal-de-mafra","city":"mafra","name":"Biblioteca Municipal de Mafra","category":"library","description":"Main municipal library of Mafra, holding about 68,000 documents, open to the public for reading and study. In summer it switches to a weekday-only timetable.","address":"Rua José Elias Garcia, 2640-495 Mafra","lat":38.93751,"lng":-9.33098,"website":"https://www.cm-mafra.pt/pages/1034?poi_id=58","phone":"+351 261 815 422","opening_hours":"Tu-Sa 10:00-13:00,14:00-19:00","hours_source":"website","access":"open","access_note":"Public municipal library; Wi-Fi and study-seat details are not stated on the municipal page. Summer (15 July-15 September): Mo-Fr 10:00-13:00 and 14:00-19:00, closed Saturday. Closed on public holidays.","coord_precision":"venue"},
{"slug":"25-pm-coffee-nusa-dua","city":"nusa-dua","name":"25:PM Coffee Nusa Dua","category":"cafe","description":"Two-storey cafe in a shop-house complex on the Bypass at Puri Bendesa, open until midnight, with a coworking-style area upstairs. Reviewers and a travel-media write-up mention table sockets, Wi-Fi, music at moderate volume and outdoor seating.","address":"Komplek Ruko Puri Bendesa I No. 5-6, Jl. Bypass Ngurah Rai, Mumbul, Nusa Dua, Badung, Bali 80361","lat":-8.78565,"lng":115.20026,"phone":"+62 813-3997-9075","opening_hours":"Mo-Su 08:00-24:00","hours_source":"listing","access":"open","access_note":"Walk-in cafe; no booking needed, and staff expect you to order food or drinks while you work.","coord_precision":"street"},
{"slug":"honey-bread-cafe-nusa-dua","city":"nusa-dua","name":"Honey & Bread Cafe","category":"cafe","description":"Cafe on the Bypass near Nusa Dua, part of the Rama restaurant group. Travel sites tag it as laptop-friendly and mention free Wi-Fi. Opening hours differ between sources, so check before travelling.","address":"Jl. Bypass Ngurah Rai KM 25, Nusa Dua, Benoa, Kuta Selatan, Badung, Bali","lat":-8.79736,"lng":115.22089,"website":"https://honeyandbread.ramarestaurantsbali.com/","phone":"+62 361 776316","access":"open","access_note":"Walk-in cafe; no booking needed, and staff expect you to order food or drinks while you work.","coord_precision":"street"},
{"slug":"smaranala-coffee-eatery-nusa-dua","city":"nusa-dua","name":"SMARANALA Coffee & Eatery","category":"cafe","description":"Multi-level cafe with on-site rooms in the Taman Mumbul Estate, with an air-conditioned indoor area, outdoor tables and a balcony. BaliFolio and Google reviews from 2025-2026 describe a second-floor co-working area, plenty of power outlets and decent Wi-Fi. It sits in a residential area off the main road and dogs live on site.","address":"Taman Mumbul Estate, Jl. Taman Kebo Iwa Kav. 83, Nusa Dua, Badung, Bali 80361","lat":-8.79474,"lng":115.20868,"outdoor_seating":"yes","access":"open","access_note":"Walk in. Hours were not confirmed by more than one listing: check before going.","coord_precision":"venue"},
{"slug":"hub-bali-coworking-nusa-dua","city":"nusa-dua","name":"Hub Bali Coworking Nusa Dua","category":"coworking","description":"Shophouse coworking space on the Bypass Ngurah Rai in Mumbul, on the northern edge of Nusa Dua, with a shower room. Registered members have 24/7 access. Prices (website, Nov 2026, incl. tax and service as published): day 125,000 IDR, week 600,000 IDR, month 1,200,000 IDR.","address":"Jl. Bypass Ngurah Rai, Komplek Ruko Puri Bendesa I, Ruko 5-6, Mumbul, Nusa Dua 80361","lat":-8.78565,"lng":115.20026,"website":"https://hubbali.co/hub-coworking-nusa-dua/","phone":"+6282210131702","access":"registration","access_note":"Day pass for non-members.","coord_precision":"venue"},
{"slug":"bali-eco-deli-nusa-lembongan","city":"nusa-lembongan","name":"Bali Eco Deli","category":"cafe","description":"Health-food cafe in Jungutbatu that advertises a Starlink connection, solar power, outlets at several tables and a quiet window 07:00-09:00 and 15:00-18:00. The site asks for a minimum spend of IDR 50,000 and solo workers to use small tables or bar seating.","address":"Jl. Jungutbatu, Nusa Lembongan, Klungkung","lat":-8.67194,"lng":115.44934,"website":"https://baliecodeli.net/coworking-nusa-lembongan-starlink-wifi/","opening_hours":"Mo-Su 07:00-21:00","hours_source":"website","access":"open","access_note":"Walk in. Minimum spend of IDR 50,000; semi-outdoor, best for short sessions per one guide.","coord_precision":"venue"},
{"slug":"kayu-lembongan-nusa-lembongan","city":"nusa-lembongan","name":"Kayu Lembongan","category":"cafe","description":"Garden café and restaurant in a traditional wooden joglo just off the main road in Jungutbatu. Its listing on The Lembongan Traveller advertises fast Wi-Fi and plenty of power points, and an island blog says its Wi-Fi handles video calls and the airy room is good on hot days.","address":"Jl. Jungutbatu, Nusa Lembongan, Bali 80771, Indonesia","lat":-8.67102,"lng":115.44722,"website":"https://kayulembongan.com/","phone":"+62 878-5180-6128","opening_hours":"Mo-Su 07:00-22:00","hours_source":"website","access":"open","access_note":"Walk in; no booking needed. Order food or drinks to use a table.","coord_precision":"venue"},
{"slug":"koko-beach-cafe-coworking-nusa-lembongan","city":"nusa-lembongan","name":"KOKO Beach Cafe & Coworking","category":"cafe","description":"Beachfront cafe-coworking venue on the Jungutbatu shoreline with Starlink Wi-Fi, laptop-height tables, indoor and outdoor seating and a pool. Listing sites and a Nusa Lembongan island guide describe it as a place to work for the day while ordering food and coffee. Prices not published.","address":"Jl. Jungutbatu, Jungutbatu, Nusa Lembongan, Klungkung, Bali 80771","lat":-8.66368,"lng":115.45566,"phone":"+62 813-3686-203","access":"open","access_note":"Walk-in beachfront cafe; no day-pass price is published, so expect to order food or drinks while you work. Opening hours differ between listings (7:30-20:00 vs 7:00-22:00).","coord_precision":"street"},
{"slug":"milo-oliver-nusa-lembongan","city":"nusa-lembongan","name":"Milo & Oliver","category":"cafe","description":"Cozy all-day-brunch coffee shop in Jungutbatu that describes itself as a place to work, hold small meetings or play board games. A March 2026 island guide lists fast Wi-Fi and full air-conditioning, and a Dec 2025 reviewer reports 5G internet upstairs and downstairs.","address":"Jl. Jungutbatu, Dusun Kelod II, Jungutbatu, Kec. Nusa Penida, Klungkung, Bali 80771, Indonesia","lat":-8.66995,"lng":115.44985,"phone":"+628133618262","access":"open","access_note":"Walk in; no booking needed. Order food or drinks to use a table. Opening hours differ between listings (one shows closed Mondays), so check before going.","coord_precision":"street"},
{"slug":"nisi-house-of-mediterranean-nusa-lembongan","city":"nusa-lembongan","name":"Nisi - House of Mediterranean","category":"cafe","description":"Air-conditioned Mediterranean cafe in Jungut Batu village that markets itself on its own site as a work-from cafe with fast Wi-Fi tested for video calls and good coffee. Only the venue itself makes this claim, so check the connection on arrival.","address":"Jungutbatu, Nusa Lembongan, Nusa Penida, Klungkung","lat":-8.67163,"lng":115.44947,"website":"https://www.nisilembongan.co/","phone":"+62 819-3006-2023","opening_hours":"Mo-Su 07:00-23:00","hours_source":"website","access":"open","access_note":"Walk in. Open daily 07:00-23:00 per the venue. Cashless: card or bank transfer only per a venue-group post. The venue's own site makes the Wi-Fi claim, so check the connection on arrival.","coord_precision":"venue"},
{"slug":"the-general-nusa-lembongan","city":"nusa-lembongan","name":"The General","category":"cafe","description":"Bakery-cafe on the main street of Jungutbatu a few steps from the beach, serving Blacklist roasted coffee by day and turning into a pizza and wine bar after 17:00. A local island guide says it has reliable Wi-Fi and outlets under the seats; hours match across three listings.","address":"Jl. Jungutbatu, Jungutbatu, Nusa Lembongan, Klungkung 80771","lat":-8.67366,"lng":115.44917,"opening_hours":"Mo-Su 07:00-22:00","hours_source":"listing","access":"open","access_note":"Walk in. Wi-Fi claim comes from a single local guide; evenings turn into a wine bar.","coord_precision":"venue"},
{"slug":"tigerlilly-s-cafe-nusa-lembongan","city":"nusa-lembongan","name":"Tigerlilly's Cafe","category":"cafe","description":"Semi-outdoor poolside cafe inside Tigerlillys Boutique Hotel in Jungutbatu, across the road from The General. Its listing on The Lembongan Traveller advertises fibre Wi-Fi up to 45 Mbps, universal power points and comfortable seating, and a March 2026 island guide repeats that Wi-Fi and plugs are accessible.","address":"Jungutbatu, Nusa Lembongan, Klungkung, Bali 80771, Indonesia","lat":-8.67366,"lng":115.44917,"access":"open","access_note":"Walk in; no booking needed. Order food or drinks to use a table. Part of a boutique hotel; the speed figure is the venue's own claim.","coord_precision":"street"},
{"slug":"white-corner-coffee-shop-nusa-lembongan","city":"nusa-lembongan","name":"White Corner Coffee Shop","category":"cafe","description":"Family-owned beachfront coffee shop on the Jungutbatu shore with a shaded deck. The venue advertises free Wi-Fi and invites guests to spend the day working there, and the deck faces the surf. Wi-Fi speed is not published.","address":"Pantai Jungutbatu, Nusa Lembongan, Kabupaten Klungkung, Bali 80771, Indonesia","lat":-8.67926,"lng":115.44571,"website":"http://www.whitecornercoffeeshop.com/","phone":"+62 823 2288 9379","opening_hours":"Mo-Su 07:00-22:00","hours_source":"website","outdoor_seating":"yes","access":"open","access_note":"Walk in; no booking needed. Order food or drinks to use a table. The venue says open 7 days, but some map listings show Wednesday closed, so check before going.","coord_precision":"venue"},
{"slug":"kalm-cowork-lounge-nusa-lembongan","city":"nusa-lembongan","name":"Kalm Cowork Lounge","category":"coworking","description":"Air-conditioned cowork lounge inside Kalm Lembongan in Banjar Kaja, Jungutbatu, with dedicated work areas, sofa seating and garden tables. Food and coffee are delivered from the Kalm kitchen, it is open to non-guests, and guests of Kalm get free access. Prices (website pass sheet, Nov 2026, incl. 10% tax and 6% service): day 120,000 IDR, week 470,000 IDR, month 1,650,000 IDR.","address":"Kalm Lembongan, Banjar Kaja, Jungutbatu, Nusa Lembongan, Klungkung, Bali 80771","lat":-8.67053,"lng":115.44989,"phone":"+62 813-5398-376","opening_hours":"Mo-Su 08:00-19:00","hours_source":"listing","access":"registration","access_note":"Open to everyone on the island; buy a daily, weekly or monthly Cowork Pass (free for Kalm guests).","coord_precision":"street"},
{"slug":"penida-colada-nusa-penida","city":"nusa-penida","name":"Penida Colada","category":"cafe","description":"Beachfront restaurant and bar near the Ped harbour that lists free Wi-Fi on its own site. Two travel blogs name it the most popular daytime work spot on Nusa Penida, with high Wi-Fi scores and unlimited water refills, but seating is not ergonomic and it gets lively in the evening with live music from 7 pm.","address":"Jl. Raya Toya Pakeh - Ped, Nusa Penida, Klungkung Regency, Bali 80771, Indonesia","lat":-8.67579,"lng":115.51204,"website":"https://penidacolada.com/","opening_hours":"Mo-Su 08:00-23:00","hours_source":"website","outdoor_seating":"yes","access":"open","access_note":"Walk in; no booking needed. Order food or drinks to use a table. Beach-bar atmosphere; work in the daytime before the evening music.","coord_precision":"venue"},
{"slug":"bean-cafe-pererenan","city":"pererenan","name":"Bean Cafe Pererenan","category":"cafe","description":"A cafe with a co-working layout on the Pererenan stretch of Jl. Raya Canggu. Directories rate it highly for remote work, and several list it as a cafe with coworking seating. Listings mostly show 8am to 4pm daily but some differ, so check before going.","address":"Jl. Raya Canggu No.99, Pererenan, Kec. Mengwi, Kabupaten Badung, Bali 80361","lat":-8.63373,"lng":115.13793,"phone":"+62 813-3748-5933","access":"open","access_note":"Walk-in customers; buy food or drinks. Check with staff whether any co-working area has its own pricing.","coord_precision":"street"},
{"slug":"buanas-beans-coffee-shop-pererenan","city":"pererenan","name":"Buanas Beans Coffee Shop","category":"cafe","description":"A compact, plant-filled cafe on Jl. Sempol with indoor and outdoor seating. Directories describe fast Wi-Fi, air-conditioning, power outlets and a quiet, cosy mood for focused laptop sessions or a slow brunch. Small space, so seats can run out at brunch time.","address":"Jl. Sempol No.26a, Pererenan, Kec. Mengwi, Kabupaten Badung, Bali 80351","lat":-8.63975,"lng":115.13671,"phone":"+62 821-4534-0848","opening_hours":"Mo-Su 07:00-16:00","hours_source":"listing","access":"open","access_note":"Walk-in customers; buy food or drinks. Third-party sources only.","coord_precision":"street"},
{"slug":"front-cafe-pererenan","city":"pererenan","name":"Front Cafe Pererenan","category":"cafe","description":"Small open-air cafe on the main road in Pererenan. Listings describe good Wi-Fi and power outlets and a following among remote workers; one older visitor review found the connection not always stable and the room hot by day.","address":"Jl. Pantai Pererenan No.72, Pererenan, Mengwi, Badung, Bali 80351","lat":-8.64152,"lng":115.12961,"phone":"+62 818-871-688","outdoor_seating":"yes","access":"open","access_note":"Hours differ between sources: check before going.","coord_precision":"venue"},
{"slug":"hussle-cafe-pererenan","city":"pererenan","name":"Hussle Cafe","category":"cafe","description":"A colourful, hip-hop-themed cafe (previously Nipsey) on Jl. Sempol. Reviews report good Wi-Fi and plugs indoors and outdoors and a welcoming work culture. It can get busier around midday, but there are quieter corners.","address":"Jl. Sempol No.22, Pererenan, Kec. Mengwi, Kabupaten Badung, Bali 80351","lat":-8.64047,"lng":115.13535,"phone":"+62 823-4069-2414","access":"open","access_note":"Walk-in customers; buy food or drinks. Third-party sources only.","coord_precision":"street"},
{"slug":"kotta-kopi-prive-pererenan","city":"pererenan","name":"Kotta Kopi Prive Pererenan","category":"cafe","description":"A spacious cafe on Jl. Sempol with rice-field views and a large outdoor area. Directories report reliable Wi-Fi, many charging points, air-conditioning and plenty of regulars working there. It can get busier in the evening and hours differ between listings, so none are given.","address":"Jl. Sempol No.58, Pererenan, Kec. Mengwi, Kabupaten Badung, Bali 80351","lat":-8.63609,"lng":115.13903,"phone":"+62 818-0875-5685","access":"open","access_note":"Walk-in customers; buy food or drinks. Third-party sources only.","coord_precision":"street"},
{"slug":"noah-cafe-co-working-pererenan","city":"pererenan","name":"NOAH Cafe & Co-working","category":"cafe","description":"Pererenan cafe with a small air-conditioned coworking nook downstairs and couches upstairs. Guides report a plug at every table, fast Wi-Fi and free use of the coworking area with a purchase. The AC room is tiny, so arriving early is advised.","address":"Jl. Pantai Pererenan No.60, Pererenan, Mengwi, Badung, Bali 80351","lat":-8.64031,"lng":115.13063,"access":"open","access_note":"Hours differ between sources: check before going.","coord_precision":"venue"},
{"slug":"shortcut-cafe-canggu-pererenan","city":"pererenan","name":"Shortcut Cafe Canggu, Pererenan","category":"cafe","description":"A spacious, colourful Pererenan cafe with free Wi-Fi, plenty of plugs and good coffee. Sources describe a strong laptop-work culture and a generally breezy, quiet atmosphere, but the open frontage lets in traffic noise and there is no air-conditioning.","address":"Jl. Sempol No.19A, Pererenan, Kec. Mengwi, Kabupaten Badung, Bali 80351","lat":-8.64032,"lng":115.1358,"phone":"+62 821-4784-2085","access":"open","access_note":"Walk-in customers; buy food or drinks. Third-party sources only.","coord_precision":"street"},
{"slug":"tata-pererenan","city":"pererenan","name":"TaTa Pererenan","category":"cafe","description":"Small second-floor cafe in Pererenan. Directory listings report Wi-Fi, air conditioning and a calm setting, and reviewers mention laptop work.","address":"Jl. Dalem Lingsir No.1, Pererenan, Mengwi, Badung, Bali 80351","lat":-8.6454,"lng":115.12719,"phone":"+62 838-7073-2090","outdoor_seating":"yes","access":"open","access_note":"Hours differ between sources: check before going.","coord_precision":"venue"},
{"slug":"woods-bali-pererenan","city":"pererenan","name":"WOODS Bali","category":"cafe","description":"Pererenan cafe-restaurant whose own blog post presents it as a place to work, with a second-floor work area, stable Wi-Fi and outlets. The post mentions a 200,000 IDR minimum spend for working there. The kitchen takes a break from 17:00 to 18:00, though drinks are still served.","address":"Jl. Dalem Lingsir No.8, Pererenan, Mengwi, Badung, Bali","lat":-8.64598,"lng":115.1281,"website":"https://woodsbali.com/","phone":"+62 853-3393-5558","opening_hours":"Mo-Su 08:00-23:00","hours_source":"website","access":"open","access_note":"Opening hours as stated on the venue blog; verify before going.","coord_precision":"venue"},
{"slug":"argil-coworking-pererenan","city":"pererenan","name":"Argil Coworking","category":"coworking","description":"Compact coworking space in Pererenan with a staffed day-pass desk. Day passes run only during staffed hours: Monday to Friday 8am-8pm and Saturday and Sunday 9am-1pm. Prices (website, Nov 2026, tax included as published): day 250,000 IDR.","address":"Jl. Munduk Kedungu No.30, Pererenan, Mengwi, Badung 80351","lat":-8.65013,"lng":115.12661,"website":"https://argil.work/","opening_hours":"Mo-Fr 08:00-20:00; Sa,Su 09:00-13:00","hours_source":"website","access":"registration","access_note":"Day pass bookable through the website.","coord_precision":"venue"},
{"slug":"at-06-coworking-pererenan","city":"pererenan","name":"AT 06 Coworking","category":"coworking","description":"Restaurant, gym and air-conditioned coworking floor north of Echo Beach. Listings and the venue blog describe daily, weekly and monthly passes and a Skype/call room. Prices not published.","address":"Jl. Pantai Batu Mejan No.6, Canggu, Kuta Utara, Badung 80361","lat":-8.65254,"lng":115.12515,"website":"https://at06bali.com/coworking/","phone":"+628999666420","access":"open","access_note":"Walk-in; the venue blog also mentions free coworking with a minimum food and drink spend.","coord_precision":"venue"},
{"slug":"tribal-bali-coworking-hostel-pererenan","city":"pererenan","name":"Tribal Bali Coworking Hostel","category":"coworking","description":"Coworking hostel with a large open downstairs work area, pool and cafe a short walk from Pererenan Beach. Outside visitors do not need a day pass: they order food or drinks and may be asked for a minimum spend after a few hours. Prices not published.","address":"Gg. Tribal, Jl. Pantai Pererenan, Pererenan, Mengwi, Badung 80351","lat":-8.64883,"lng":115.125,"website":"https://tribalbali.com/","phone":"+6282147914973","access":"open","access_note":"Free to work with a food or drink order; reported 100,000 IDR minimum spend after about 3 hours (third-party listings).","coord_precision":"venue"},
{"slug":"o-spot-ribamar","city":"ribamar","name":"O Spot Ribamar","category":"cafe","description":"Neighbourhood café-snack bar next to the Associação de Moradores de Ribamar on the EN 247, with a terrace, parking and Wi-Fi. The venue posted in 2025 that there is space to relax or to work on a laptop, and a February 2026 review calls it perfect to chill and work.","address":"Estrada Nacional 247, Km 46, Associação de Moradores de Ribamar, 2640-027 Santo Isidoro (Ribamar)","lat":39.00726,"lng":-9.4191,"phone":"+351 937 557 778","outdoor_seating":"yes","access":"open","access_note":"Order at the counter; opening hours differ between sources so none are listed. The latest activity found was in early 2026, so check it is still open.","coord_precision":"venue"},
{"slug":"cliff-co-work-space-santa-cruz-torres-vedras","city":"santa-cruz-torres-vedras","name":"CLIFF Co-Work Space","category":"coworking","description":"Cowork room at the back of the Cliff Surf House in A dos Cunhados, about a 20-minute walk along the coast from Santa Cruz, with desks, power outlets, a big presentation screen and a view over the pool. Free for house guests, but locals and outside visitors can book desks, and lunch and coffee are available on site. The venue advertises high-speed internet but publishes no speed figure. Prices (website, Nov 2026, VAT status not stated): day 15 EUR, half day 10 EUR, week (Mon-Fri) 50 EUR, month (four weeks Mon-Fri) 150 EUR.","address":"Rua Barbosa do Bocage 14, 2560-051 A dos Cunhados","lat":39.13781,"lng":-9.36707,"website":"https://cliffcowork.com/","phone":"+351 911 731 874","opening_hours":"Mo-Su 09:00-20:00","hours_source":"website","day_pass_price_cents":1500,"access":"registration","access_note":"Book a desk in advance via WhatsApp (+351 911 731 874) or the website; outside guests are welcome. Sits inside a surf house, so expect some surf-camp activity at the front of the property.","coord_precision":"street"},
{"slug":"biblioteca-municipal-de-santa-cruz-santa-cruz-torres-vedras","city":"santa-cruz-torres-vedras","name":"Biblioteca Municipal de Santa Cruz","category":"library","description":"Small municipal library in Santa Cruz, run by Torres Vedras, which reopened on 2 April 2025. It offers on-site reading, internet access and computers for work, plus printing and reading activities.","address":"Rua Dr. Esteves de Oliveira 4 r/c, Santa Cruz, Torres Vedras","lat":39.13527,"lng":-9.38145,"website":"https://www.biblioteca-tvedras.pt/informacoes/horarios-localizacao","phone":"+351 261 933 543","opening_hours":"We-Sa 10:00-13:00,14:00-18:00","hours_source":"website","access":"open","access_note":"Public access; borrowing needs registration. Holiday closures are not stated on the page. Summer (July-August): Mo-Sa 10:00-13:00 and 14:00-18:00.","coord_precision":"venue"},
{"slug":"blend-cafe-sanur","city":"sanur","name":"Blend Cafe Sanur","category":"cafe","description":"Calm garden cafe on Jl. Pungutan, away from the beachfront strip. DeskBean reports reliable Wi-Fi and relaxed seating, Honeycombers describes it as a quiet place to finish work, and Go Bali Go lists it as a work cafe suited to a few hours. Prices and menu run to bowls, coffee and desserts.","address":"Jl. Pungutan No. 48, Sanur, Denpasar Selatan, Denpasar, Bali 80228","lat":-8.69116,"lng":115.26022,"phone":"+62 812-1598-4375","opening_hours":"Mo-Su 07:30-22:00","hours_source":"listing","outdoor_seating":"yes","access":"open","access_note":"Walk in. Several listings agree on 07:30-22:00 daily.","coord_precision":"venue"},
{"slug":"bull-s-coffee-sanur","city":"sanur","name":"Bull's Coffee Sanur","category":"cafe","description":"Coffee shop near Sindhu Beach on Jl. Pantai Sindhu, open from morning to late evening. Third Desk and DeskBean list it as laptop-friendly with no known time limit, and the brand's own site gives the Sanur address and phone.","address":"Jl. Pantai Sindhu No. 7, Sanur, Denpasar Selatan, Denpasar, Bali 80228","lat":-8.68048,"lng":115.25899,"website":"https://bullscoffee.id/","phone":"+62 895-2476-4911","opening_hours":"Mo-Su 07:00-22:00","hours_source":"website","access":"open","access_note":"Walk-in cafe; no booking needed, and staff expect you to order food or drinks while you work.","coord_precision":"street"},
{"slug":"cafe-bloom-bali-bloomwerk-sanur","city":"sanur","name":"Cafe Bloom Bali & BloomWerk","category":"cafe","description":"Cafe Bloom is a Sanur cafe on Jl. Danau Toba with an associated BloomWerk space. Its own website shows different opening hours for each part and notes that the main cafe is screen-free on Wednesdays, so check before bringing a laptop that day. Closed on Sundays.","address":"Jl. Danau Toba No. 12, Sanur, Denpasar Selatan, Denpasar, Bali 80228","lat":-8.68487,"lng":115.26055,"website":"https://cafebloombali.com/","opening_hours":"Mo-Sa 07:00-16:00","hours_source":"website","access":"open","access_note":"Walk-in; laptops are not welcome in the main cafe on Wednesdays, so check the site for the current rule.","coord_precision":"street"},
{"slug":"coffee-therapy-sanur","city":"sanur","name":"Coffee Therapy Sanur","category":"cafe","description":"Small, bright cafe on the Ngurah Rai Bypass in Sanur with manual-brew coffee, bagels and brunch dishes. Multiple reviewers and a local expat blog (Feb 2026) report Wi-Fi, sockets and air-conditioning, and say parking can be tight. It is closed on Sundays and closes in the afternoon.","address":"Jl. Bypass Ngurah Rai No. 33, Sanur Kaja, Denpasar Selatan, Denpasar, Bali 80227","lat":-8.67387,"lng":115.25968,"phone":"+62 821-4487-3333","access":"open","access_note":"Walk-in cafe; no booking needed, and staff expect you to order food or drinks while you work.","coord_precision":"venue"},
{"slug":"from-here-sanur","city":"sanur","name":"From Here","category":"cafe","description":"All-day cafe in a restored joglo with gardens and a fish pond, opened in mid-2026 on Jl. Danau Poso. Honeycombers describes an air-conditioned work area with no minimum spend, and a Tripadvisor review from April 2026 mentions power sockets near the tables and working on a laptop. Wi-Fi speed has not been verified.","address":"Jl. Danau Poso No. 54, Sanur, Denpasar Selatan, Denpasar, Bali 80228","lat":-8.70592,"lng":115.25374,"website":"https://fromhererestaurant.com/","phone":"+62 813-3788-700","opening_hours":"Mo-Su 06:30-22:00","hours_source":"website","outdoor_seating":"yes","access":"open","access_note":"Walk in. Several listings agree on 06:30-22:00 daily; tables can be booked via WhatsApp.","coord_precision":"venue"},
{"slug":"gecko-coffee-house-sanur","city":"sanur","name":"Gecko Coffee House","category":"cafe","description":"Small neighbourhood coffee house on Jl. Danau Poso in Sanur that publishes its own address and hours on a simple site. Travel blogs and review sites mention it as a spot to sit with a laptop. It closes mid-afternoon.","address":"Jl. Danau Poso No. 40, Sanur Kauh, Denpasar Selatan, Denpasar, Bali","lat":-8.70573,"lng":115.25397,"website":"https://geckocoffeehouse.wixsite.com/my-site","phone":"+62 361 3352165","opening_hours":"Mo-Su 07:00-15:00","hours_source":"website","access":"open","access_note":"Walk-in cafe; no booking needed, and staff expect you to order food or drinks while you work.","coord_precision":"street"},
{"slug":"genius-cafe-sanur","city":"sanur","name":"Genius Cafe","category":"cafe","description":"Bamboo open-air hall on Mertasari Beach in south Sanur, long used by remote workers and the wellness crowd, serving bowls and lighter plates. Honeycombers and Go Bali Go both describe it as a place to work with a sea view, with comfortable seating and little traffic noise. There is no air-conditioning, and midday glare and heat can be strong.","address":"Mertasari Beach (Jl. Kusuma Sari / Jl. Sudamala area), Sanur Kauh, Denpasar Selatan, Denpasar, Bali","lat":-8.71145,"lng":115.25375,"website":"https://geniuscafebali.com/","opening_hours":"Mo-Su 07:00-22:00","hours_source":"website","outdoor_seating":"yes","access":"open","access_note":"Walk in. Open air with no air-conditioning; daily 07:00-22:00 per the venue.","coord_precision":"venue"},
{"slug":"koru-kulture-sanur","city":"sanur","name":"Koru Kulture","category":"cafe","description":"Small cafe and clothing boutique on Jl. Batur Sari, west of the Bypass, serving brunch, smoothie bowls, sandwiches and New Zealand-style pies. A 2025 reviewer who works on a laptop there calls it computer-friendly, and listings mark it as laptop-friendly with no known time limit. Wi-Fi is not documented.","address":"Jl. Batur Sari No. 43, Sanur, Denpasar Selatan, Denpasar, Bali 80228","lat":-8.69488,"lng":115.25458,"access":"open","access_note":"Walk-in cafe; no booking needed, and staff expect you to order food or drinks while you work.","coord_precision":"street"},
{"slug":"medin-bali-cafe-coffee-sanur","city":"sanur","name":"Medin Bali Cafe & Coffee","category":"cafe","description":"Air-conditioned cafe on Jl. Danau Tamblingan that regularly appears in Sanur work-cafe guides. Visitors mention plenty of seating and outlets. Noise levels are mixed: one directory calls it loud at busy times, while a nomad testing site rates it relatively free of traffic noise.","address":"Jl. Danau Tamblingan No. 34, Sanur, Denpasar Selatan, Denpasar, Bali 80228","lat":-8.68599,"lng":115.26233,"opening_hours":"Mo-Su 07:00-23:00","hours_source":"listing","access":"open","access_note":"Walk-in cafe; no booking needed, and staff expect you to order food or drinks while you work.","coord_precision":"street"},
{"slug":"mushroom-espresso-sanur","city":"sanur","name":"Mushroom Espresso Sanur","category":"cafe","description":"Colourful, bohemian-style cafe on Jl. Danau Toba with sofa seating and a short brunch menu; a sister cafe sits on Nusa Lembongan. Local press, DeskBean and Honeycombers describe plentiful power sockets and a quiet atmosphere, which suits light laptop work.","address":"Jl. Danau Toba No. 5C, Sanur, Denpasar Selatan, Denpasar, Bali 80228","lat":-8.68487,"lng":115.26055,"phone":"+62 819-3435-8002","opening_hours":"Mo-Su 07:00-20:00","hours_source":"listing","access":"open","access_note":"Walk-in cafe; no booking needed, and staff expect you to order food or drinks while you work.","coord_precision":"street"},
{"slug":"over-the-moon-cafe-sanur","city":"sanur","name":"Over The Moon Cafe","category":"cafe","description":"Spacious all-day cafe on Jl. Danau Tamblingan with indoor air-conditioning and a patio. DeskBean and Twork describe reliable Wi-Fi, outlets and people working on laptops, and Honeycombers' Sanur guide says its author has worked there, preferring the patio mid-morning. The cafe also runs a happy hour from 16:00, so the room gets livelier later in the day.","address":"Jl. Danau Tamblingan No. 19, Sanur, Denpasar Selatan, Denpasar, Bali 80228","lat":-8.685472,"lng":115.262336,"website":"https://www.overthemoonbali.com/","phone":"+62 822-2551-1012","opening_hours":"Mo-Su 08:00-21:00","hours_source":"website","outdoor_seating":"yes","access":"open","access_note":"Walk in. The venue's site says open daily 08:00-21:00; some third-party listings show slightly different opening times.","coord_precision":"venue"},
{"slug":"senjadibali-coffee-garden-sanur","city":"sanur","name":"Senjadibali Coffee & Garden","category":"cafe","description":"Garden-style cafe set back from the Bypass in Sanur, mostly outdoor seating among plants plus a small air-conditioned room shared with a pie shop. Reviewers report good Wi-Fi and many sockets, with mosquitoes outdoors and uneven service as the main complaints. Closes at 18:00.","address":"Jl. Bypass Ngurah Rai No. 385, Sanur Kauh, Denpasar Selatan, Denpasar, Bali","lat":-8.70457,"lng":115.2522,"phone":"+62 813-1169-5594","opening_hours":"Mo-Su 09:00-18:00","hours_source":"listing","access":"open","access_note":"Walk-in cafe; no booking needed, and staff expect you to order food or drinks while you work.","coord_precision":"street"},
{"slug":"stuja-di-pantai-sanur","city":"sanur","name":"Stuja di Pantai","category":"cafe","description":"Beachfront cafe on Jl. Kusuma Sari with outdoor beanbag seating, a second floor and an air-conditioned room. Third Desk (checked Oct 2026) lists laptops as welcome with Wi-Fi available, detik lists Wi-Fi and sockets among the facilities, and Honeycombers calls the Wi-Fi dependable. Live music runs in the evenings and the sea breeze can be strong.","address":"Jl. Kusuma Sari No. 4, Sanur, Denpasar Selatan, Denpasar, Bali 80239","lat":-8.70703,"lng":115.26248,"website":"https://stuja.id/","opening_hours":"Mo-Su 06:00-23:00","hours_source":"website","outdoor_seating":"yes","access":"open","access_note":"Walk in. Opens daily 06:00-23:00 per the venue's site.","coord_precision":"venue"},
{"slug":"flow-workspace-sanur","city":"sanur","name":"FLOW Workspace Sanur","category":"coworking","description":"Coworking space in the Sanur Kauh area west of the beach strip, with day passes for visitors and 24/7 access for registered members. Prices (website, Nov 2026): day 300,000 IDR.","address":"Jl. Danau Poso No.66, Sanur, Denpasar Selatan 80228","lat":-8.70573,"lng":115.25397,"website":"https://flowworkspacebali.com/","phone":"+6282340989176","access":"registration","access_note":"Staffed hours reported M-F 9-18, Sa 9-17 by third parties; coordinate is street level (Jl. Danau Poso).","coord_precision":"venue"},
{"slug":"livit-hub-bali-sanur","city":"sanur","name":"Livit Hub Bali","category":"coworking","description":"Four-storey coworking building in Sanur, a short walk from the seafront, with a cafe floor, rooftop and meeting rooms. Members get 24/7 access and day users pick a package by floor. Prices (website, Nov 2026, incl. 11% VAT as published): Basic day 140,000 IDR.","address":"Jl. Bumi Ayu, Gg. Pungut Sari No.6, Sanur, Denpasar Selatan 80228","lat":-8.69067,"lng":115.26138,"website":"https://liv.it/livit-hub-coworking-bali/","access":"registration","access_note":"Basic day pass covers the cafe coworking area only; contact the hub to confirm staffed hours. Coordinate from a third-party place record that matches the street.","coord_precision":"venue"},
{"slug":"bread-yard-seminyak","city":"seminyak","name":"Bread Yard","category":"cafe","description":"Bakery-cafe with skylights and concrete walls on Jl. Kayu Aya, with indoor alcoves and outdoor seating. Honeycombers reports that Wi-Fi handles a normal working day and that wall tables have plugs; a Lemon8 post and a Trip.com post describe a quieter upper floor used by remote workers. Opening hours differ between the venue's site and other listings.","address":"Jl. Kayu Aya No. 12, Seminyak, Kuta, Badung, Bali 80361","lat":-8.68589,"lng":115.15591,"website":"https://bread-yard.com/","outdoor_seating":"yes","access":"open","access_note":"Walk in; outdoor seating opens later than indoor. Hours differ between sources: check before going.","coord_precision":"venue"},
{"slug":"hut-bali-seminyak","city":"seminyak","name":"HUT Bali Seminyak","category":"cafe","description":"Rooftop cafe above a bakery and concept store on a side street off Jl. Drupadi, formerly known as Shelter Cafe. A leafy upstairs room with a communal table makes it popular for a couple of hours of laptop work, and Honeycombers calls it digital-nomad friendly. Reviews on remoto.cafe are mixed on Wi-Fi reliability and the number of outlets, so it suits shorter sessions better than a full workday.","address":"Jl. Drupadi 1 No. 2b, Seminyak, Kuta, Badung, Bali 80361","lat":-8.68928,"lng":115.16681,"website":"https://hutbali.com/","phone":"+62 823-4004-0199","opening_hours":"Mo-Su 07:00-17:00","hours_source":"website","access":"open","access_note":"Walk in; the cafe is on the upper floor and closes at 17:00 per the venue's site. Wi-Fi and outlets are reported as inconsistent, so keep a backup connection.","coord_precision":"venue"},
{"slug":"milk-madu-seminyak","city":"seminyak","name":"Milk & Madu Seminyak","category":"cafe","description":"Large two-storey, fully air-conditioned branch of the Milk & Madu cafe group on the main Jl. Raya Seminyak. Downstairs is the lively family floor; the quieter upstairs floor is described by Honeycombers and Trip.com posts as a dedicated co-working-style area with sockets, big tables and good Wi-Fi. Live music runs on weekend evenings, so plan calls earlier in the day.","address":"Jl. Raya Seminyak No. 56, Seminyak, Kuta, Badung, Bali 80361","lat":-8.69409,"lng":115.16814,"website":"https://milkandmadu.com/location/","opening_hours":"Mo-Su 07:00-22:00","hours_source":"website","outdoor_seating":"yes","access":"open","access_note":"Walk in and ask for the quieter upstairs floor. Opens daily 07:00-22:00 per the venue's site.","coord_precision":"venue"},
{"slug":"moonface-seminyak","city":"seminyak","name":"Moonface Seminyak","category":"cafe","description":"Neighbourhood all-day cafe and wood-fired pizza place on Jl. Dewi Saraswati II, with air-conditioned indoor seating, a covered outdoor area and a garden. A private meeting room is offered for small groups. Nomad reviews report Wi-Fi around 90 Mbps with people working there.","address":"Jl. Dewi Saraswati II No. 7, Seminyak, Kuta, Badung, Bali 80361","lat":-8.687986,"lng":115.172612,"website":"https://moonfaceseminyak.com/","phone":"+62 817-7689-2023","opening_hours":"Mo-Su 07:00-23:00","hours_source":"website","access":"open","access_note":"Walk-in cafe; no booking needed, and staff expect you to order food or drinks while you work.","coord_precision":"street"},
{"slug":"raincoat-coffee-seminyak","city":"seminyak","name":"Raincoat Coffee","category":"cafe","description":"Specialty coffee shop on Jl. Persada in Kerobokan, just north of Seminyak. Directories list it as a place where people work on laptops during the day, with espresso drinks and light food. It closes mid-afternoon, so it suits morning and early-afternoon sessions.","address":"Jl. Persada No. 60, Kerobokan Kelod, Kuta Utara, Badung, Bali","lat":-8.67707,"lng":115.17573,"phone":"+62 853-9326-7624","opening_hours":"Mo-Fr 07:00-17:00; Sa-Su 07:00-16:00","hours_source":"listing","access":"open","access_note":"Walk-in cafe; no booking needed, and staff expect you to order food or drinks while you work.","coord_precision":"street"},
{"slug":"revolver-espresso-seminyak","city":"seminyak","name":"Revolver Espresso Seminyak","category":"cafe","description":"Espresso bar down Gang 51 off Jl. Kayu Aya, open from morning until 23:00. Several Seminyak remote-work roundups list it for coffee and laptop sessions, and the brand publishes the address and hours on its own site.","address":"Jl. Kayu Aya, Gang 51 (No. 51), Seminyak, Kuta, Badung, Bali 80361","lat":-8.68445,"lng":115.15797,"website":"https://revolverbali.com/pages/seminyak","phone":"+62 812-3842-8343","opening_hours":"Mo-Su 07:00-23:00","hours_source":"website","access":"open","access_note":"Walk-in cafe; no booking needed, and staff expect you to order food or drinks while you work.","coord_precision":"venue"},
{"slug":"titik-temu-coffee-seminyak","city":"seminyak","name":"Titik Temu Coffee Seminyak","category":"cafe","description":"Indonesian specialty-coffee roastery set down a lane off Jl. Kayu Cendana, built around a wide wooden staircase that doubles as communal seating. Honeycombers says the Wi-Fi is solid, and remoto.cafe and an Indonesian review site describe laptop use as normal, with the first floor air-conditioned and better for focused work. Opening hours differ between listings.","address":"Jl. Kayu Cendana No. 1, Uma Seminyak, Seminyak, Kuta, Badung, Bali 80361","lat":-8.68235,"lng":115.15787,"website":"https://www.titiktemu.cafe/seminyak","access":"open","access_note":"Walk in; the ground floor is the calmer work area. Hours differ between sources: check before going.","coord_precision":"venue"},
{"slug":"biliq-seminyak-coworking-seminyak","city":"seminyak","name":"Biliq Seminyak Coworking","category":"coworking","description":"Central Seminyak coworking space close to the shops and restaurants of the Oberoi strip. The website's hosting hours are marked as temporary and look out of date, so hours are omitted. Prices not published.","address":"Jl. Yudistira No.3A, Seminyak, Kuta, Badung 80361","lat":-8.69129,"lng":115.17519,"website":"https://biliqbali.com/coworkingspaceseminyak","phone":"+6281937387372","access":"registration","access_note":"Day passes reported by third-party listings at about 150,000 IDR; not on the website.","coord_precision":"venue"},
{"slug":"unionspace-seminyak","city":"seminyak","name":"UnionSPACE Seminyak","category":"coworking","description":"Branch of the Indonesian flexible-workspace chain UnionSPACE on Jl. Kayu Aya, offering a shared coworking area, private offices, meeting rooms and virtual-office services. Weekday opening only. Prices (website, Nov 2026; VAT status not stated): coworking from 50,000 IDR per half day, private office from 1,200,000 IDR per person.","address":"Jl. Kayu Aya No. 40, Seminyak, Kuta Utara, Badung, Bali 80361","lat":-8.68394,"lng":115.16219,"website":"https://unionspace.co.id/","phone":"+62 821-8000-0721","opening_hours":"Mo-Fr 09:00-18:00","hours_source":"listing","access":"registration","access_note":"Pay per half day or sign up for a membership; contact the centre first, as the space is mainly set up for business tenants.","coord_precision":"street"},
{"slug":"work-hub-co-working-space-seminyak","city":"seminyak","name":"Work-Hub Co-Working Space Seminyak","category":"coworking","description":"Coworking space on Sunset Road in Seminyak with desks, private work areas, meeting rooms and an event space, plus an on-site gym and pantry. It targets remote workers, freelancers and small teams. Day, weekly and monthly access are mentioned by directories, but the site shows its packages only as images. Prices not published.","address":"Jl. Sunset Road No. 85X, Lingk. Basangkasa, Seminyak, Kuta, Badung, Bali 80361","lat":-8.68635,"lng":115.17044,"website":"https://workhub.co.id/","phone":"+62 813-3080-9025","access":"registration","access_note":"Contact the team to book a day or a longer plan; hours are not published on the website.","coord_precision":"street"},
{"slug":"cowork-torres-vedras","city":"torres-vedras","name":"Cowork Torres Vedras","category":"coworking","description":"Large 1000 m2 coworking and incubation centre near the centre of Torres Vedras with open-space desks, private studios, meeting and training rooms and a lounge. Desks can be rented by the hour, day, week or month. Prices (website, Nov 2026, excl. VAT): open-space desk from 89 EUR/month, studios from 180 EUR/month; day rate not published on the site.","address":"Rua Dr. Gomes Leal 3A, 2560-331 Torres Vedras","lat":39.09533,"lng":-9.25834,"website":"https://www.coworktorresvedras.pt/","phone":"+351 261 408 673","opening_hours":"Mo-Fr 09:00-19:00","hours_source":"website","access":"open","access_note":"Flexible hourly, daily, weekly and monthly desk plans are advertised on the website; ask the team for the day rate.","coord_precision":"venue"},
{"slug":"the-cube-cowork-coffee-torres-vedras","city":"torres-vedras","name":"The Cube - Cowork & Coffee","category":"coworking","description":"Small independent coworking in Torres Vedras, a few minutes from the town centre, with free on-site parking and a cafe-bar serving Italian-style coffee and light meals. Work areas include an 18-seat shared table in a lounge with a hanging Japanese garden, private rooms, a team room (Lux) and a meeting room (Teka). Prices not published.","address":"Rua Adão de Carvalho 4, 2560-574 Torres Vedras","lat":39.10737,"lng":-9.25766,"website":"https://thecube.pt/","phone":"+351 914 404 402","access":"registration","access_note":"No day-pass price is published, so contact the team (phone on the website) to book a seat. Opening hours are not on the website and listings disagree (09:00-18:00 vs 09:00-19:00); check before going.","coord_precision":"street"},
{"slug":"biblioteca-municipal-de-torres-vedras","city":"torres-vedras","name":"Biblioteca Municipal de Torres Vedras","category":"library","description":"Public library in the former Moagens Clemente building, with adult, youth and children's rooms and a periodicals and audiovisual room. Entry and use of the spaces are free and need no registration; a reader card is only needed to borrow items. The library FAQ confirms Wi-Fi, permission to use a laptop and power sockets.","address":"Largo Justino Freire 9, 2560-636 Torres Vedras","lat":39.09195,"lng":-9.26073,"website":"https://www.biblioteca-tvedras.pt/","phone":"+351 261 310 478","opening_hours":"Mo 14:00-18:30; Tu-Fr 10:00-18:30; Sa 14:00-18:00","hours_source":"website","access":"open","access_note":"Closed on national holidays and the municipal holiday (11 November), carnival Saturday-Tuesday and Easter Saturday per the library's page. Summer (July-August): Mo-Fr 10:00-13:00 and 14:00-18:00, closed Saturday.","coord_precision":"venue"},
{"slug":"alchemy-ubud","city":"ubud","name":"Alchemy Ubud","category":"cafe","description":"Plant-based café and wellness hub on Jalan Penestanan Kelod, long used by remote workers. Independent 2026 guides report fast Wi-Fi (about 87 Mbps down in one test) and good outlet access, but the room is lively with no call booths, so calls pick up background chatter. Arrive early for a good seat.","address":"Jl. Penestanan Kelod No.75, Sayan, Kecamatan Ubud, Kabupaten Gianyar, Bali 80571, Indonesia","lat":-8.50639,"lng":115.25164,"website":"https://alchemybali.co","access":"open","access_note":"Walk in; no booking needed. Order food or drinks to use a table. Busy at peak meal times; prices are on the high side for Ubud.","coord_precision":"venue"},
{"slug":"anomali-coffee-ubud","city":"ubud","name":"Anomali Coffee Ubud","category":"cafe","description":"Branch of the Indonesian specialty-coffee chain on Ubud's main road. Several 2025-2026 guides and user reviews describe it as a dependable place for laptops, with an air-conditioned room, many outlets and steady Wi-Fi, though one review complains about table cleanliness and food is basic. Hours differ between listings.","address":"Jl. Raya Ubud No. 88, Ubud","lat":-8.50821,"lng":115.2652,"website":"https://store.anomalicoffee.com","phone":"+62 361 972263","access":"open","access_note":"Walk in. Hours differ between sources (about 07:00-21:00 or 22:00): check before going.","coord_precision":"venue"},
{"slug":"bgs-ubud-coffee-bar-ubud","city":"ubud","name":"BGS Ubud Coffee Bar","category":"cafe","description":"Small coffee bar and surf/skate shop in Penestanan that lists free Wi-Fi, outdoor seating and a community feel on its own page. A Jan 2026 user test found about 58 Mbps down, and a 2025 listing mentions sockets; one review complains that the low tables are awkward for laptops and another that Wi-Fi was switched off.","address":"Jl. Penestanan, Sayan, Ubud 80571","lat":-8.50594,"lng":115.25077,"website":"https://bgs.surf/store/bgs-ubud/","opening_hours":"Mo-Su 06:30-21:00","hours_source":"website","outdoor_seating":"yes","access":"open","access_note":"Walk in. Seating is limited and low; ask staff for the Wi-Fi.","coord_precision":"venue"},
{"slug":"decafo-cafe-ubud","city":"ubud","name":"Decafo Cafe","category":"cafe","description":"Tiny Ghibli-inspired café in Lodtunduh, south of Ubud, with books, quiet music and strong coffee. A directory calls it a peaceful work-friendly café and reviewers mention working or reading there, but seating is limited and afternoons get crowded, so mornings are best. The coordinates are street-level on Jalan A.A. Gede Rai.","address":"Jl. A.A. Gede Rai No.90, Lodtunduh, Kecamatan Ubud, Kabupaten Gianyar, Bali 80571, Indonesia","lat":-8.53717,"lng":115.26253,"access":"open","access_note":"Walk in; no booking needed. Order food or drinks to use a table. Lodtunduh is a few kilometres south of central Ubud. One listing shows Wednesday closed; check before going.","coord_precision":"street"},
{"slug":"den-o-coffee-eatery-ubud","city":"ubud","name":"Den~O Coffee & Eatery","category":"cafe","description":"Two-storey café in Kedewatan, on the Sanggingan-Lungsiakan road north-west of the centre. Reviewers describe strong air-conditioning, very fast Wi-Fi, many power sockets and a quiet room suited to work. The coordinates are street-level and the café is about 2-3 km from central Ubud.","address":"Jl. Raya Lungsiakan No.44, Kedewatan, Kecamatan Ubud, Kabupaten Gianyar, Bali 80571, Indonesia","lat":-8.48571,"lng":115.24708,"access":"open","access_note":"Walk in; no booking needed. Order food or drinks to use a table.","coord_precision":"street"},
{"slug":"gangga-coffee-ubud","city":"ubud","name":"Gangga Coffee Ubud","category":"cafe","description":"Kintamani-coffee cafe and roastery on Jl. Raya Andong in Peliatan. The operator's own guide advertises fibre Wi-Fi, an air-conditioned indoor room, outlets at nearly every table and a quieter upstairs; an Aug 2026 user test and several reviews support this. The venue's pages disagree on closing time (16:00 vs 18:00).","address":"Jl. Raya Andong No. 11, Peliatan, Ubud","lat":-8.5034,"lng":115.27232,"website":"https://ganggacoffee.com/locations/ubud/","phone":"+62 811-3822-2477","access":"open","access_note":"Walk in, no reservation needed. Closing time differs between the venue's own pages (16:00 or 18:00): check before going.","coord_precision":"venue"},
{"slug":"home-cafe-jatayu-ubud","city":"ubud","name":"HOME Cafe Jatayu","category":"cafe","description":"Air-conditioned brunch cafe with full-length windows on Jl. Jatayu in Peliatan. Twork users measured very fast Wi-Fi and reviews call it quiet with big tables, though one review says outlets are limited to one wall and the wicker chairs get uncomfortable.","address":"Jl. Jatayu No. 18, Peliatan, Ubud 80571","lat":-8.51679,"lng":115.26634,"access":"open","access_note":"Walk in. Parking is tight at busy hours; opening hours differ between listings, so check before going.","coord_precision":"venue"},
{"slug":"jabarano-coffee-ubud","city":"ubud","name":"Jabarano Coffee","category":"cafe","description":"Halal Indonesian specialty coffee house on Jl. Goutama with two floors and a small prayer room. Honeycombers (2026) and DeskBean describe fast Wi-Fi, plugs and a calm layout for working.","address":"Jl. Goutama No. 15, Ubud 80571","lat":-8.50903,"lng":115.26422,"website":"https://www.jabaranocoffee.com/","phone":"+62 811-1118-1515","opening_hours":"Mo-Su 07:00-22:00","hours_source":"listing","access":"open","access_note":"Walk in; order via QR at the table. Hours from Tripadvisor and Honeycombers.","coord_precision":"venue"},
{"slug":"kafe-ubud","city":"ubud","name":"KAFE","category":"cafe","description":"Relaxed multi-level café and restaurant on Jalan Hanoman with air-conditioning and quiet corners. Reviewers report quick Wi-Fi and say it is a good place to get work done, and a 2025-2026 listing rates it a dependable work-and-linger choice. It can get moderately busy at meal times.","address":"Jl. Hanoman No.44B, Ubud, Kecamatan Ubud, Kabupaten Gianyar, Bali 80571, Indonesia","lat":-8.51391,"lng":115.26413,"website":"https://kafe-bali.com/","phone":"+62 811-1793-455","opening_hours":"Mo-Su 07:00-23:00","hours_source":"website","access":"open","access_note":"Walk in; no booking needed. Order food or drinks to use a table.","coord_precision":"venue"},
{"slug":"komorebi-ubud-onigiri-cafe-ubud","city":"ubud","name":"Komorebi Ubud Onigiri Cafe","category":"cafe","description":"Small, quiet Japanese-style cafe (onigiri, matcha, specialty coffee) just off the centre on Jl. Sugriwa. DeskBean and an Aug 2026 Twork test report free Wi-Fi (about 88 Mbps), outlets and calm conditions. Capacity is small and opening days are reported inconsistently.","address":"Jl. Sugriwa No. 12, Ubud 80571","lat":-8.511,"lng":115.26566,"phone":"+62 813-1855-3508","access":"open","access_note":"Walk in. Reported closing days are unclear (Twork says Monday and Wednesday): check on Instagram @komorebi.bali before going. Coordinate is for the street segment.","coord_precision":"venue"},
{"slug":"kopi-pangeran-ubud","city":"ubud","name":"Kopi Pangeran Ubud","category":"cafe","description":"Hidden-garden coffee shop in Penestanan built around a courtyard tree, with AC, good-value coffee and pastries. Reviewers report fast free Wi-Fi and well-placed power points. Seating is limited and parking is a short walk away.","address":"Jl. Penestanan, Sayan, Kecamatan Ubud, Kabupaten Gianyar, Bali 80517, Indonesia","lat":-8.50613,"lng":115.25396,"access":"open","access_note":"Walk in; no booking needed. Order food or drinks to use a table.","coord_precision":"venue"},
{"slug":"lazy-cats-cafe-ubud","city":"ubud","name":"Lazy Cats Cafe","category":"cafe","description":"Vegetarian cafe with an upper-floor terrace overlooking Jl. Raya Ubud and a vintage-lounge interior. Blogs and user speed tests report fast Wi-Fi and sockets, and reviewers describe working there for long periods.","address":"Jl. Raya Ubud No. 11, Ubud 80571","lat":-8.50532,"lng":115.25835,"website":"https://lazycatsubud.com/","phone":"+62 812-4652-4975","outdoor_seating":"yes","access":"open","access_note":"Walk in. Hours differ slightly between sources (own site says 08:00-21:00).","coord_precision":"venue"},
{"slug":"littletalks-ubud","city":"ubud","name":"Littletalks Ubud","category":"cafe","description":"Indonesian bistro with a community library and reading room, now on Jl. Bisma (older listings still show a Jl. Raya Campuhan address). Tripadvisor text and a 2026 nomad blog describe it as a calm place to read or work, and a 2025 review notes stable Wi-Fi after an initial connection hiccup.","address":"Jl. Bisma No. 77, Ubud 80571 (ground floor of Ani's Villas)","lat":-8.51276,"lng":115.25824,"phone":"+62 859-2044-4300","access":"open","access_note":"Walk in. Hours differ between listings (08:00-18:00 to 22:00), so check before an evening visit.","coord_precision":"venue"},
{"slug":"livingstone-holyground-ubud","city":"ubud","name":"Livingstone Holyground","category":"cafe","description":"Spacious garden café and bakery in Peliatan, known for pastries and a tropical courtyard. Reviewers say it is a good place to open a laptop for breakfast or a long coffee, and a directory scores it well for working; Wi-Fi speed is not documented, so test it before a call.","address":"Jl. Raya Andong No.88x, Peliatan, Kecamatan Ubud, Kabupaten Gianyar, Bali 80571, Indonesia","lat":-8.5047,"lng":115.27218,"access":"open","access_note":"Walk in; no booking needed. Order food or drinks to use a table.","coord_precision":"venue"},
{"slug":"lucky-family-coffee-food-ubud","city":"ubud","name":"Lucky Family Coffee & Food","category":"cafe","description":"Multi-level café-restaurant on Jalan Bisma with indoor and outdoor seating, board games and an upstairs room that listings describe as good for a long laptop session. Reviewers mention good Wi-Fi and plenty of plug sockets. The coordinates are street-level only, so the entrance may be a short walk from the marker.","address":"Jl. Bisma, Ubud, Kecamatan Ubud, Kabupaten Gianyar, Bali 80571, Indonesia","lat":-8.5161,"lng":115.258,"access":"open","access_note":"Walk in; no booking needed. Order food or drinks to use a table. Opening hours differ between listings, so check before going.","coord_precision":"street"},
{"slug":"milk-madu-ubud","city":"ubud","name":"Milk & Madu Ubud","category":"cafe","description":"Branch of the Bali brunch-cafe group opposite Ubud Palace. A Twork review measured fast Wi-Fi (about 130 Mbps) with many outlets and big tables, but it gets noisy around midday. Open daily until 22:00.","address":"Jl. Suweta No. 3, Ubud 80571","lat":-8.50633,"lng":115.26248,"website":"https://milkandmadu.com/location/","opening_hours":"Mo-Su 07:00-22:00","hours_source":"website","access":"open","access_note":"Walk in. Quietest in the morning or mid-afternoon.","coord_precision":"venue"},
{"slug":"monkey-cave-espresso-ubud","city":"ubud","name":"Monkey Cave Espresso Ubud","category":"cafe","description":"Tiny specialty-coffee stop on Monkey Forest Road with an upstairs deck used by laptop workers. Twork (Aug 2026) measured about 51 Mbps with outlets, and DeskBean and Google-based reviews note strong Wi-Fi but limited seating and road noise.","address":"Jl. Monkey Forest No. 88, Ubud 80571","lat":-8.51834,"lng":115.26237,"access":"open","access_note":"Walk in. Hours differ between sources (closing 18:00 to 22:00): check before going.","coord_precision":"venue"},
{"slug":"muse-cafe-art-ubud","city":"ubud","name":"Muse Cafe & Art","category":"cafe","description":"Calm, plant-filled café on Jalan Sri Wedari with a bohemian interior and an Indian-inspired menu. Several reviewers describe fast internet and a peaceful atmosphere for remote work during the day, but reviewers report laptops are not allowed after about 18:00. Food and service reviews are mixed.","address":"Jl. Sri Wedari No.6b, Ubud, Kecamatan Ubud, Kabupaten Gianyar, Bali 80571, Indonesia","lat":-8.49416,"lng":115.26646,"website":"https://musebali.com","phone":"+62 811 3809 394","access":"open","access_note":"Walk in and order food or drinks. Reviewers report no laptop use after about 18:00, so plan to work in the daytime; hours differ between Google and the venue site.","coord_precision":"venue"},
{"slug":"namaskara-coffee-superfoods-ubud","city":"ubud","name":"Namaskara Coffee & Superfoods","category":"cafe","description":"Vegetarian-friendly café on Jalan Tirta Tawar in Petulu, east of the centre, with indoor air-conditioned seating and some outdoor tables. Reviewers report good Wi-Fi and charging points at most tables, and the café is a regular casual work spot. Street noise is mentioned by one guest.","address":"Jl. Tirta Tawar No.50, Petulu, Kecamatan Ubud, Kabupaten Gianyar, Bali 80571, Indonesia","lat":-8.50877,"lng":115.26825,"access":"open","access_note":"Walk in; no booking needed. Order food or drinks to use a table.","coord_precision":"venue"},
{"slug":"old-friends-coffee-ubud","city":"ubud","name":"Old Friends Coffee","category":"cafe","description":"Small farmer-and-roaster café in Mas serving Kintamani coffee, quiet and cozy. Reviewers say it is a pleasant place to work, though seating is limited and laptop evidence is thin, so it suits shorter sessions. The owner's site says it is occasionally closed for religious events.","address":"Jl. Nyuh Bojog No. 5, Mas, Ubud 80571","lat":-8.52254,"lng":115.25676,"opening_hours":"Mo,We-Su 08:00-16:00","hours_source":"website","access":"open","access_note":"Walk in; no booking needed. Order food or drinks to use a table. Closed Tuesdays per the owner's site; sometimes closed for religious events.","coord_precision":"street"},
{"slug":"opini-kopi-ubud","city":"ubud","name":"Opini Kopi","category":"cafe","description":"Affordable breakfast café in Peliatan with an upstairs and rooftop area that remote workers favour. Listings confirm Wi-Fi and outlets, though one reviewer calls the connection good enough rather than amazing, and street noise and heat can intrude. The coordinates are street-level on Jalan Sukma Kesuma.","address":"Jl. Sukma Kesuma No.59, Tebesaya, Peliatan, Ubud, Kecamatan Ubud, Kabupaten Gianyar, Bali 80571, Indonesia","lat":-8.51645,"lng":115.26693,"access":"open","access_note":"Walk in; no booking needed. Order food or drinks to use a table. Upstairs is usually the better place to work.","coord_precision":"street"},
{"slug":"pukako-by-paddyfield-ubud","city":"ubud","name":"Pukako by Paddyfield","category":"cafe","description":"Open-air panini and coffee cafe on a path beside the rice terraces off Jl. Subak Sok Wayah. A 2026 blog, DeskBean and a local review describe strong Wi-Fi and charging points, and say staff are fine with long stays. No air conditioning, and mosquitoes are likely in the evening.","address":"Jl. Subak Sok Wayah, Ubud 80571","lat":-8.50235,"lng":115.25716,"outdoor_seating":"yes","access":"open","access_note":"Walk in. Listings disagree on hours (about 07:00 to 20:00 or 21:00): check before going. Mornings are quietest.","coord_precision":"venue"},
{"slug":"sayuri-healing-food-cafe-academy-ubud","city":"ubud","name":"Sayuri Healing Food Cafe & Academy","category":"cafe","description":"Plant-based and raw-food cafe with a garden, a main room and a quieter upstairs with low tables. Reviewers and travel blogs describe working on laptops upstairs and having charging spots, though the main room hosts music and events and outlet evidence is thin. Open late, which suits evening sessions.","address":"Jl. Sukma Kesuma No. 2, Peliatan, Ubud 80571","lat":-8.50992,"lng":115.26893,"website":"https://sayurihealingfood.com/","phone":"+62 822-4048-5154","opening_hours":"Mo-Su 08:00-23:00","hours_source":"website","access":"open","access_note":"Walk in. Kitchen last order 22:00. Choose the upstairs or garden for quieter work.","coord_precision":"venue"},
{"slug":"schauberger-coffee-ubud","city":"ubud","name":"Schauberger Coffee","category":"cafe","description":"Small vegan coffee shop in Penestanan with high stools facing the street. Listings report free Wi-Fi, and reviewers call it quiet and good for working or reading, though street noise and limited seating can interrupt deep focus. The coordinates are street-level only.","address":"Jl. Banjar Penestanan Kaja No.52, Sayan, Kecamatan Ubud, Kabupaten Gianyar, Bali 80571, Indonesia","lat":-8.50374,"lng":115.24717,"opening_hours":"Mo-Su 06:00-19:00","hours_source":"website","access":"open","access_note":"Walk in; no booking needed. Order food or drinks to use a table.","coord_precision":"street"},
{"slug":"seniman-coffee-studio-ubud","city":"ubud","name":"Seniman Coffee Studio","category":"cafe","description":"Specialty roaster-cafe a short walk from Ubud Palace, roasting Indonesian beans on site. The venue's own listing advertises fast Wi-Fi; guides and an Aug 2026 user speed test report working Wi-Fi, shared tables and sockets, plus an air-conditioned room downstairs. It gets loud and crowded after mid-morning, so mornings suit laptop work best.","address":"Jl. Sri Wedari No. 5, Banjar Taman Kelod, Ubud","lat":-8.50673,"lng":115.2652,"website":"https://www.senimancoffee.com/seniman-ubud/","phone":"+62 812-8338-6641","opening_hours":"Mo-Su 07:30-22:00","hours_source":"website","access":"open","access_note":"Walk in. Order at the venue; expect crowds and noise after about 10:00.","coord_precision":"venue"},
{"slug":"suka-espresso-ubud","city":"ubud","name":"Suka Espresso Ubud","category":"cafe","description":"Australian-style all-day cafe on Jl. Raya Pengosekan, part of Suka Collective. The operator's site pitches it for remote-working afternoons, and guides and user tests report Wi-Fi around 25-78 Mbps; one test warns of noise and few sockets. It turns into a dinner and bar venue in the evening.","address":"Jl. Raya Pengosekan No. 108, Ubud 80571","lat":-8.52114,"lng":115.26321,"website":"https://www.sukacollective.co/suka-ubud","phone":"+62 813-3869-2319","opening_hours":"Mo-Su 07:30-22:00","hours_source":"website","access":"open","access_note":"Walk in. Best used in the morning; sockets can be scarce and evenings are busy.","coord_precision":"venue"},
{"slug":"sunny-coffee-ubud","city":"ubud","name":"Sunny Coffee","category":"cafe","description":"Small coffee shop on Jalan Hanoman, on the road towards the Monkey Forest, with a ground-floor room and an upstairs terrace. Google reviewers describe it as a good place to work on a laptop with fast Wi-Fi, and one directory reports a few outlets, but seating is limited and many customers take drinks away. One reviewer found the Wi-Fi weaker upstairs.","address":"Jl. Hanoman No. 36, Ubud, Kecamatan Ubud, Kabupaten Gianyar, Bali 80571, Indonesia","lat":-8.5127,"lng":115.26423,"phone":"+62 822-3708-7274","access":"open","access_note":"Walk in; no booking needed. Order food or drinks to use a table. Best for a short solo session because seating is limited.","coord_precision":"venue"},
{"slug":"the-hidden-space-cafe-ubud","city":"ubud","name":"The Hidden Space Cafe","category":"cafe","description":"Small cafe among rice fields and gardens south of central Ubud that positions itself for remote workers. Its own site advertises fibre Wi-Fi (50+ Mbps claimed), power at every seat and laptop-friendly tables, and 2026 listings confirm it is open. It closes on Sundays and the entrance is easy to miss, so use the map pin.","address":"Jl. Dangin Labak, Singakerta, Ubud 80571","lat":-8.52767,"lng":115.24958,"website":"https://thehiddensapceubud.blog/","phone":"+62 896-8490-8897","opening_hours":"Mo-Sa 09:00-18:00","hours_source":"website","outdoor_seating":"yes","access":"open","access_note":"Walk in, no booking needed. Closed Sundays; some directories list 10:00-19:00 instead of the venue's own 09:00-18:00.","coord_precision":"venue"},
{"slug":"the-hideout-cafe-ubud","city":"ubud","name":"The Hideout Cafe Ubud","category":"cafe","description":"Air-conditioned café tucked away on Jalan Kajeng, a short walk north of the palace. Listings describe stable Wi-Fi, power points and a calm, nicely decorated room that suits remote work. One guest reported inattentive service. The coordinates are street-level only.","address":"Jl. Kajeng No.37, Ubud, Kecamatan Ubud, Kabupaten Gianyar, Bali 80571, Indonesia","lat":-8.50121,"lng":115.26343,"access":"open","access_note":"Walk in; no booking needed. Order food or drinks to use a table.","coord_precision":"street"},
{"slug":"titik-temu-coffee-ubud-palace-ubud","city":"ubud","name":"Titik Temu Coffee - Ubud Palace","category":"cafe","description":"Café on Jalan Suweta in the Ubud Palace area with a roomy layout and a mix of indoor, outdoor and counter seating. Listings describe it as work-friendly, with fast Wi-Fi and plenty of sockets, and note that the indoor air-conditioning can feel weak and music can be loud at times. The coordinates are only street-level, so the exact entrance may be a few doors away.","address":"Jl. Suweta No.6, Ubud, Kecamatan Ubud, Kabupaten Gianyar, Bali 80571, Indonesia","lat":-8.5055,"lng":115.26296,"access":"open","access_note":"Walk in; no booking needed. Order food or drinks to use a table. Can get busy; the quieter indoor or upstairs seats suit work best.","coord_precision":"street"},
{"slug":"tucky-specialty-coffee-brunch-ubud","city":"ubud","name":"Tucky Specialty Coffee & Brunch","category":"cafe","description":"Specialty-coffee and brunch cafe on Jalan Goutama Selatan. Its own site says guests are welcome to settle in with a book or laptop, and reviewers report reliable Wi-Fi and air-conditioning. Seating is compact and stool-heavy, so it suits short to medium sessions better than all-day work. From 16:00 it becomes the sister wine and tapas bar Bacari.","address":"Jl. Goutama Sel. No.15, Ubud, Kecamatan Ubud, Kabupaten Gianyar, Bali 80571, Indonesia","lat":-8.50983,"lng":115.2641,"website":"https://tuckybali.com/","phone":"+62 811-3811-7613","opening_hours":"Mo-Su 09:00-16:00","hours_source":"website","access":"open","access_note":"Walk in; no booking needed. Order food or drinks to use a table. Closes at 16:00 daily.","coord_precision":"venue"},
{"slug":"two-face-ubud","city":"ubud","name":"Two Face Ubud","category":"cafe","description":"Brunch cafe on Jalan Raya Ubud (the palace road) with an open-concept room and indoor seating. Its own site welcomes remote workers and directories mention charging ports, but road noise and music make it less suited to deep-focus work. It closes at 14:00.","address":"Jl. Raya Ubud, Ubud, Kecamatan Ubud, Kabupaten Gianyar, Bali 80571, Indonesia","lat":-8.50627,"lng":115.26088,"website":"https://www.twofacebali.com/two-face-ubud","opening_hours":"Mo-Su 07:30-14:00","hours_source":"website","access":"open","access_note":"Walk in; no booking needed. Order food or drinks to use a table. Closes at 14:00 daily.","coord_precision":"street"},
{"slug":"ubud-coffee-roastery-ubud","city":"ubud","name":"Ubud Coffee Roastery","category":"cafe","description":"Small specialty roastery-cafe on Jalan Goutama Selatan with a limited indoor room and outdoor tables along the street. Directories list it as work-friendly with Wi-Fi, but reviewer reports on connection speed are mixed, so test it before a video call, and outlets are limited.","address":"Jl. Goutama Sel. No.27x, Ubud, Kecamatan Ubud, Kabupaten Gianyar, Bali 80571, Indonesia","lat":-8.51178,"lng":115.26384,"website":"http://ubudcoffeeroastery.com/","phone":"+62 811-3800-8001","access":"open","access_note":"Walk in; no booking needed. Order food or drinks to use a table. Listings give about 07:00-18:30 daily; the venue's own site could not be checked, so confirm before going.","coord_precision":"venue"},
{"slug":"umbi-cafe-bali-ubud","city":"ubud","name":"Umbi Cafe Bali","category":"cafe","description":"Calm, cosy cafe in Penestanan with indoor and outdoor seating and a menu built around locally grown vegetables and house drinks. Directory listings report fast Wi-Fi and available outlets, and reviewers describe it as peaceful, with some roadside noise.","address":"Jl. Penestanan Kelod, Sayan, Kecamatan Ubud, Kabupaten Gianyar, Bali 80571, Indonesia","lat":-8.50643,"lng":115.25117,"access":"open","access_note":"Walk in; no booking needed. Order food or drinks to use a table.","coord_precision":"street"},
{"slug":"unity-cafe-bali-ubud","city":"ubud","name":"Unity Cafe Bali","category":"cafe","description":"Gluten-free vegetarian and vegan-friendly cafe west of central Ubud, away from the traffic. Its own site advertises fast Wi-Fi, plenty of indoor and outdoor seating, parking, and invites guests to stay as long as they like. Kitchen last order is 15:45, so it suits morning and lunch sessions only.","address":"Jl. Raya Lungsiakan No. 49, Ubud","lat":-8.48592,"lng":115.248,"website":"https://www.unitycafebali.com","phone":"+62 822-1013-1708","opening_hours":"Mo-Su 08:15-16:00","hours_source":"website","outdoor_seating":"yes","access":"open","access_note":"Walk in. Closes at 16:00 daily, last order 15:45. Coordinates are from the venue's own embedded map.","coord_precision":"venue"},
{"slug":"watercress-ubud","city":"ubud","name":"Watercress Ubud","category":"cafe","description":"Plant-filled café near Monkey Forest Road with free Wi-Fi and sockets at many tables. Reviewers use it for casual laptop sessions, though daytime heat and occasional live music can limit focus.","address":"Jl. Monkey Forest, Ubud, Bali, Kabupaten Gianyar, Bali 80571, Indonesia","lat":-8.51317,"lng":115.26087,"website":"https://watercressbali.com/","opening_hours":"Mo-Su 07:00-22:00","hours_source":"website","access":"open","access_note":"Walk in; no booking needed. Order food or drinks to use a table.","coord_precision":"venue"},
{"slug":"yellow-flower-cafe-ubud","city":"ubud","name":"Yellow Flower Cafe","category":"cafe","description":"Family-run garden café above the rice fields in the Penestanan hills, reached on foot via the Penestanan steps and a footpath. Reviewers say Wi-Fi works in the larger back seating area but not in the small front section, and there are few or no power sockets, so bring a charged laptop. It is quiet and suits a couple of hours of focused work rather than a full day.","address":"Jl. Raya Campuhan, Sayan, Kecamatan Ubud, Kabupaten Gianyar, Bali 80571, Indonesia","lat":-8.50216,"lng":115.25185,"website":"https://yellow-flower-cafe.com/","phone":"+62 812-3889-9695","opening_hours":"Mo-Su 07:00-21:00","hours_source":"website","access":"open","access_note":"Walk in; no booking needed. Order food or drinks to use a table. Hard to find: follow the footpath from the Penestanan steps (scooter parking below). Sit in the back area for Wi-Fi.","coord_precision":"venue"},
{"slug":"zest-ubud","city":"ubud","name":"Zest Ubud","category":"cafe","description":"Large open-air plant-based restaurant-cafe in Penestanan with jungle views, sofas and big tables. Blogs from 2023-2026 report good Wi-Fi and power outlets and that staff do not mind long stays, but it is busy, noisy at peak hours and fairly pricey, so arrive early for a wall outlet.","address":"Jl. Raya Penestanan Kelod No. 8, Penestanan, Ubud 80571","lat":-8.50502,"lng":115.25378,"website":"https://www.zestubud.com/","phone":"+62 823-4006-5048","opening_hours":"Mo-Su 08:00-22:00","hours_source":"website","access":"open","access_note":"Walk in. Busy at lunch; limited outlets away from the walls.","coord_precision":"venue"},
{"slug":"outpost-ubud-nyuh-kuning-coworking-ubud","city":"ubud","name":"Outpost Ubud Nyuh Kuning Coworking","category":"coworking","description":"Outpost's original Ubud coworking, started in 2016 near the Monkey Forest end of Nyuh Kuning. It has an air-conditioned downstairs focus room, an open-air upstairs area, private offices and video-call booths, and is open 24 hours. An 8-hour day pass costs IDR 258,000 per Outpost's member portal; passes are sold at the host desk.","address":"Jl. Raya Nyuh Kuning, Mas, Ubud, Gianyar 80571","lat":-8.52762,"lng":115.2557,"website":"https://destinationoutpost.co/location/ubud/","phone":"+623619080584","opening_hours":"24/7","hours_source":"website","access":"registration","access_note":"Day pass at the host desk (also listed in the Outpost member portal); the same pass works at Outpost Penestanan.","coord_precision":"venue"},
{"slug":"outpost-ubud-penestanan-coworking-ubud","city":"ubud","name":"Outpost Ubud Penestanan Coworking","category":"coworking","description":"Outpost's Penestanan site combines coliving and a 24-hour coworking space on the hill west of central Ubud, with a glassed-in air-conditioned focus zone and an open-air rooftop area. An 8-hour day pass costs IDR 258,000 per Outpost's member portal and can be bought on-site at the host desk.","address":"Jl. Penestanan, Penestanan, Sayan, Ubud, Gianyar 80571","lat":-8.50669,"lng":115.25167,"website":"https://destinationoutpost.co/cowork-in-ubud-penestanan/","phone":"+623619080584","opening_hours":"24/7","hours_source":"website","access":"registration","access_note":"Day pass at the host desk or via the Nexudus portal.","coord_precision":"venue"},
{"slug":"setter-ubud","city":"ubud","name":"SETTER Ubud","category":"coworking","description":"Ubud branch of the SETTER coworking brand in a shophouse block on Jl. Raya Sanggingan, with open desks, focus rooms, a podcast room, an event space and a cafe. The brand's website advertises a daily pass from IDR 299,000 and 24/7 access across its locations.","address":"The Tjampuhan View Ruko Blok F, Jl. Raya Sanggingan No.88X, Ubud, Gianyar 80571","lat":-8.49823,"lng":115.25332,"website":"https://setter.work/","opening_hours":"24/7","hours_source":"website","access":"registration","access_note":"Day pass price is from the operator's site; confirm that the Ubud branch honours it before going.","coord_precision":"venue"},
{"slug":"ubud-coworking-ubud","city":"ubud","name":"Ubud Coworking","category":"coworking","description":"Coworking space in the rice-field village of Petulu, north-east of central Ubud. Its website lists daily opening 08:00-22:00, and third-party guides say day passes are sold to visitors. Prices not published.","address":"Jl. Raya Andong No.92, Petulu, Ubud, Gianyar 80571","lat":-8.50022,"lng":115.27262,"website":"https://ubudcoworking.com/","phone":"+6288210300222","opening_hours":"Mo-Su 08:00-22:00","hours_source":"website","access":"registration","access_note":"Day pass offered to visitors per third-party listings; coordinate is street level (Jl. Raya Andong).","coord_precision":"venue"},
{"slug":"ubud-space-coworking-and-coffee-ubud","city":"ubud","name":"Ubud.Space Coworking and Coffee","category":"coworking","description":"Coworking space and cafe in central Ubud with open space and bookable meeting rooms, advertising 200 Mbps internet. The website lists open-space passes at IDR 40,000 per hour and IDR 170,000 per day.","address":"F7V5+RF, Ubud, Gianyar 80571 (Plus Code; central Ubud)","lat":-8.50544,"lng":115.25869,"website":"https://ubud.space/","phone":"+628113859118","access":"registration","access_note":"Listings show about 9:00-23:30 daily; the website gives no street address, only a Plus Code.","coord_precision":"venue"},
{"slug":"alchemy-uluwatu","city":"uluwatu","name":"Alchemy Uluwatu","category":"cafe","description":"Plant-based cafe on a garden plot on Jl. Pantai Bingin with a build-your-own salad bar, a shop and a limited air-conditioned section. Guides report that people work on laptops here, with a Wi-Fi connection that holds up for a normal day, and a Japanese travel blog notes laptops in the indoor shop area. Menu is entirely plant-based and prices are above the Bali average; the air-conditioned part reportedly fills up by late morning.","address":"Jl. Pantai Bingin No. 8, Pecatu, Kuta Selatan, Badung, Bali 80361","lat":-8.81452,"lng":115.11319,"phone":"+62 811-3888-143","outdoor_seating":"yes","access":"open","access_note":"Walk in; arrive early for the air-conditioned section. Hours differ slightly between sources: check before going.","coord_precision":"venue"},
{"slug":"artisan-bingin-uluwatu","city":"uluwatu","name":"Artisan Bingin","category":"cafe","description":"Bakery and restaurant on Jl. Pantai Bingin with house pastries and sourdough by day. Guides report an air-conditioned upstairs floor with plugs used as an informal coworking area in the daytime, while the ground floor is no-laptop and the whole venue is reserved for dinner guests after about 18:00. The Artisan group says free Wi-Fi is available at its locations.","address":"Jl. Pantai Bingin, Pecatu, Kuta Selatan, Badung, Bali 80361","lat":-8.81227,"lng":115.1133,"access":"open","access_note":"Laptops only upstairs and only in the daytime; downstairs is no-laptop and evenings are for dinner guests. Listings give roughly 07:00-23:00 daily; check before going.","coord_precision":"venue"},
{"slug":"baked-uluwatu","city":"uluwatu","name":"BAKED. Uluwatu","category":"cafe","description":"Bakehouse on Jl. Labuansait with fresh pastries, sourdough and specialty coffee, plus an all-day breakfast and sandwich menu. Honeycombers calls it a compact, cool room suited to a focused three or four hour session, and Third Desk lists laptops as welcome with Wi-Fi available and a quiet room. Card payments only according to Third Desk.","address":"Jl. Labuansait No. 10 Unit 11, Pecatu, Kuta Selatan, Badung, Bali 80361","lat":-8.81664,"lng":115.09282,"access":"open","access_note":"Walk in. Guides and listings agree on roughly 07:00-17:00 daily; it is compact, so not ideal for an all-day stay.","coord_precision":"venue"},
{"slug":"expat-roasters-uluwatu","city":"uluwatu","name":"Expat. Roasters Uluwatu","category":"cafe","description":"Uluwatu branch of the Expat. Roasters group on Jl. Pantai Cemongkak, serving specialty coffee and food. Its own site lists the address and daily hours. Work guides describe single wall tables that each have a plug, which suits solo laptop sessions better than group calls.","address":"Jl. Pantai Cemongkak No. 9F, Pecatu, Kuta Selatan, Badung, Bali 80361","lat":-8.81671,"lng":115.11985,"website":"https://expatroasters.com/pages/expat-roasters-uluwatu-bali","phone":"+62 812-3889-8406","opening_hours":"Mo-Su 06:30-19:00","hours_source":"website","access":"open","access_note":"Walk-in cafe; no booking needed, and staff expect you to order food or drinks while you work. Wall tables are single seats.","coord_precision":"street"},
{"slug":"karmafree-surf-shop-cafe-uluwatu","city":"uluwatu","name":"KARMAFREE Surf Shop & Cafe","category":"cafe","description":"Organic cafe at the back of an eco-minded surf and clothing shop on Jl. Pantai Suluban, with shoes off at the door and a menu leaning towards healthy plates and matcha. Directories describe a calm, air-conditioned interior where people stay for hours to work or write. Hours differ between sources.","address":"Jl. Pantai Suluban, Pecatu, Kuta Selatan, Badung, Bali 80361","lat":-8.8187,"lng":115.08847,"access":"open","access_note":"Walk-in cafe; no booking needed, and staff expect you to order food or drinks while you work.","coord_precision":"street"},
{"slug":"lemanja-uluwatu","city":"uluwatu","name":"Lemanja Uluwatu","category":"cafe","description":"Poolside cafe on Jl. Labuansait with a coworking area. Its own site advertises fast Wi-Fi and all-day access, and guides such as Mindseat and Little Bingin list it as a dependable Uluwatu work spot.","address":"Jl. Labuansait No. 168, Pecatu, Kuta Selatan, Badung, Bali 80361","lat":-8.82421,"lng":115.12246,"website":"https://lemanjabali.com/","phone":"+62 823-4061-0168","opening_hours":"Mo-Su 07:00-22:00","hours_source":"website","access":"open","access_note":"Walk-in; order food or drinks to use the cafe and its coworking area.","coord_precision":"street"},
{"slug":"the-loft-uluwatu","city":"uluwatu","name":"The Loft Uluwatu","category":"cafe","description":"High-ceilinged all-day cafe on Jl. Labuansait near Padang Padang, popular with Uluwatu remote workers. Guides mention charging sockets, good Wi-Fi and a dog-friendly, relaxed atmosphere.","address":"Jl. Labuansait No. 52, Pecatu, Kuta Selatan, Badung, Bali 80361","lat":-8.81417,"lng":115.11231,"website":"https://theloft-bali.com/","phone":"+62 821-4073-9515","opening_hours":"Mo-Su 07:30-22:00","hours_source":"website","access":"open","access_note":"Walk-in cafe; no booking needed, and staff expect you to order food or drinks while you work.","coord_precision":"street"},
{"slug":"ulu-garden-uluwatu","city":"uluwatu","name":"Ulu Garden","category":"cafe","description":"Tropical garden restaurant of the Ulu Tribe complex serving modern Indonesian food, with live music and events in the evening. Honeycombers says laptops are openly welcome by day; a travel guide and Nomadwise list co-working-style areas, sockets and Wi-Fi. It is open-air with no air-conditioning, and gets lively after dark.","address":"Jl. Pantai Padang-Padang, Pecatu, Kuta Selatan, Badung, Bali 80361","lat":-8.81654,"lng":115.09338,"website":"https://ulutribe.com/ulu-garden/","phone":"+62 813-3954-5241","opening_hours":"Mo-Su 07:00-23:00","hours_source":"website","outdoor_seating":"yes","access":"open","access_note":"Walk in; daytime is calmer for work. The venue's contact page lists the garden 07:00-23:00 while its FAQ says open from 7 AM until late; check before going.","coord_precision":"venue"},
{"slug":"bwork-uluwatu","city":"uluwatu","name":"BWork Uluwatu","category":"coworking","description":"Uluwatu branch of the BWork coworking and cafe brand, with coworking open 24/7 and a cafe on separate hours. The website lists a day pass at IDR 299,000 (199,000 for Indonesian ID holders) and a weekend day pass at IDR 200,000.","address":"Jl. Labuansait No.169, Pecatu, Kuta Selatan, Badung 80361","lat":-8.82349,"lng":115.12047,"website":"https://bwork.id/membership/uluwatu/","opening_hours":"24/7","hours_source":"website","access":"registration","access_note":"Day pass is sold via the website; confirm availability with the host before going.","coord_precision":"venue"},
{"slug":"the-space-bali-coworking-uluwatu","city":"uluwatu","name":"The Space Bali Coworking Uluwatu","category":"coworking","description":"Yoga studio and coworking space close to Bingin Beach. The website sells drop-in coworking to visitors: IDR 275,000 for a day, with cheaper weekend and after-4pm drop-ins.","address":"Jl. Pantai Bingin No.3, Pecatu, Kuta Selatan, Badung 80361","lat":-8.81221,"lng":115.11321,"website":"https://thespacebali.org/coworking-uluwatu","access":"registration","access_note":"Drop-in pass open to non-members of the yoga studio.","coord_precision":"venue"},
{"slug":"uluwatu-coworking-padang-padang-surf-camp-uluwatu","city":"uluwatu","name":"Uluwatu Coworking (Padang Padang Surf Camp)","category":"coworking","description":"Coworking space attached to a surf camp near Padang Padang beach, open around the clock. Passes are sold to outside visitors by the day, by two hours and by the week, and private offices are rented hourly. The website lists day (12 h) IDR 200,000, 2 hours IDR 100,000 and week IDR 1,000,000.","address":"Padang Padang Surf Camp, Jl. Labuan Sait, Pecatu, Kuta Selatan, Badung 80361","lat":-8.81521,"lng":115.10951,"website":"https://uluwatucoworking.com/","opening_hours":"24/7","hours_source":"website","access":"registration","access_note":"Reserve private offices via reception or email.","coord_precision":"venue"},
{"slug":"uluwatu-hub-uluwatu","city":"uluwatu","name":"Uluwatu Hub","category":"coworking","description":"Garden coworking space with an on-site cafe in Pecatu, open 24 hours a day for coworkers and closed on Nyepi. Day passes are sold walk-in only. Prices not published.","address":"Jl. Goa Lempeh No.27A, Pecatu, Kuta Selatan, Badung 80364","lat":-8.84008,"lng":115.12403,"website":"https://uluwatuhub.com/","opening_hours":"24/7","hours_source":"website","access":"registration","access_note":"Walk-in day pass valid 24h; third-party listings suggest about 200,000 IDR (not on the website).","coord_precision":"venue"},
{"slug":"7am-bakers-umalas","city":"umalas","name":"7AM Bakers Umalas","category":"cafe","description":"A stylish, spacious bakery-cafe on Jl. Bumbak Dauh, listed on the brand's own site as its Umalas outlet. DeskBean mentions charging outlets and a linger-friendly mood but also that table occupancy is limited and it can get busy, so it suits casual work better than a full-day desk session.","address":"Jl. Bumbak Dauh No.88, Kerobokan, Kec. Kuta Utara, Kabupaten Badung, Bali 80361","lat":-8.65639,"lng":115.15239,"website":"https://sevenambakers.com/","phone":"+62 811-3850-303","opening_hours":"Mo-Su 07:00-19:00","hours_source":"website","access":"open","access_note":"Walk-in customers; buy food or drinks. Third-party sources suggest staying time may be limited at busy times.","coord_precision":"venue"},
{"slug":"expat-roasters-petitenget-umalas","city":"umalas","name":"Expat. Roasters Petitenget","category":"cafe","description":"Branch of the Bali roaster Expat. Roasters on Jl. Petitenget, serving its own coffee alongside breakfast and brunch plates. Remote-work directories list it as laptop-friendly, and the roaster publishes the address and opening hours on its own site.","address":"Jl. Petitenget No. 1A, Kerobokan Kelod, Kuta Utara, Badung, Bali 80361","lat":-8.6718,"lng":115.16062,"website":"https://expatroasters.com/pages/expat-roasters-seminyak-petitenget","phone":"+62 812-4614-0493","opening_hours":"Mo-Su 06:30-19:00","hours_source":"website","access":"open","access_note":"Walk-in cafe; no booking needed, and staff expect you to order food or drinks while you work.","coord_precision":"venue"},
{"slug":"granary-cafe-workspace-umalas","city":"umalas","name":"Granary Cafe & Workspace","category":"cafe","description":"Hidden garden cafe with a dedicated workspace room, a pool area and, according to a nomad guide, outlets at nearly all seats and air-conditioning (a directory advises checking the current AC status). Both sources describe it as work-oriented.","address":"Jl. Batu Belig No.99, Kerobokan Kelod, Kuta Utara, Badung, Bali 80361","lat":-8.67312,"lng":115.14785,"outdoor_seating":"yes","access":"open","access_note":"Hours differ between sources; the venue's Instagram says open daily 08:00-17:00.","coord_precision":"venue"},
{"slug":"nude-cafe-umalas","city":"umalas","name":"nüde cafe Umalas","category":"cafe","description":"The Umalas branch of the nude cafe group, a bright cafe on Jl. Bumbak Dauh. DeskBean describes free Wi-Fi, abundant sockets and comfortable seating, but another directory rates it only average for working and one reviewer reports a restriction on laptop use, so reports are mixed. It can get busy around lunch.","address":"Jl. Bumbak Dauh No.89D, Kerobokan, Kec. Kuta Utara, Kabupaten Badung, Bali 80361","lat":-8.65481,"lng":115.15341,"website":"https://nude-bali.com/locations/umalas","phone":"+62 822-2176-3787","opening_hours":"Mo-Su 07:00-22:00","hours_source":"website","access":"open","access_note":"Walk-in customers; buy food or drinks. Laptop-friendliness is documented only by third-party directories and is mixed, so check seating and any laptop policy.","coord_precision":"street"},
{"slug":"pison-coffee-petitenget-umalas","city":"umalas","name":"Pison Coffee (Petitenget)","category":"cafe","description":"Red-brick coffee house and bakery on Jl. Petitenget with two floors, sofas and desk-style tables, roasting its own Indonesian beans. Third-party reviews describe Wi-Fi, power outlets and air-conditioning, with the upstairs floor preferred for working; live music starts in the evening, which can get loud for calls. Wi-Fi may slow down at lunch and dinner peaks according to one guide.","address":"Jl. Petitenget No. 19A, Kerobokan Kelod, Kuta Utara, Badung, Bali 80361","lat":-8.67268,"lng":115.16005,"website":"https://pisonindonesia.com/pison-seminyak/","phone":"+62 821-4456-0066","opening_hours":"Mo-Su 07:00-01:00","hours_source":"website","outdoor_seating":"yes","access":"open","access_note":"Walk in. Opens daily 07:00 until 01:00 per the venue's site; upstairs is quieter for laptop work and evening live music is louder.","coord_precision":"venue"},
{"slug":"sinamon-bali-umalas","city":"umalas","name":"Sinamon Bali Umalas","category":"cafe","description":"The flagship cinnamon-roll cafe of Sinamon, with indoor and outdoor seating and a full coffee menu. Reviews report strong Wi-Fi, sockets at tables and cool air-conditioning, though it can get crowded and parking for cars is limited. Sinamon's site confirms Wi-Fi at all branches but does not mention laptops.","address":"Jl. Bumbak Gang P. Belitung No.12, Kerobokan, Kec. Kuta Utara, Kabupaten Badung, Bali 80361","lat":-8.65222,"lng":115.15537,"website":"https://sinamon.com/cinnamon-rolls-umalas","phone":"+62 821-4444-2354","opening_hours":"Mo-Su 07:30-23:00","hours_source":"website","access":"open","access_note":"Walk-in customers; buy food or drinks. Laptop-friendliness is documented by third-party directories.","coord_precision":"venue"},
{"slug":"starbucks-canggu-square-umalas","city":"umalas","name":"Starbucks Canggu Square","category":"cafe","description":"Two-storey Starbucks in the Canggu Square complex with a spacious upstairs work area, a large desk and strong air-conditioning according to directory listings. Wi-Fi is reported to be unreliable at times, and outlets are unconfirmed.","address":"Jl. Pantai Berawa No.8, Tibubeneng, Canggu, Kuta Utara, Badung, Bali 80361","lat":-8.66359,"lng":115.1466,"access":"open","access_note":"Hours differ between sources: check before going.","coord_precision":"venue"},
{"slug":"ducat-space-umalas","city":"umalas","name":"Ducat Space","category":"coworking","description":"Coworking space and cafe in the quiet Subak Sari area between Canggu and Kerobokan. Listings give conflicting closing times, so hours are omitted. Prices not published.","address":"Jl. Subak Sari No.13, Tibubeneng, Kuta Utara, Badung 80361","lat":-8.66497,"lng":115.14716,"website":"https://ducatspace.com/","phone":"+6281244533959","access":"registration","access_note":"Contact the venue for passes; no prices published.","coord_precision":"venue"},
{"slug":"g88-coworking-umalas","city":"umalas","name":"G88 Coworking","category":"coworking","description":"Spacious coworking hall in the Gate 88 complex with long shared desks, glass meeting rooms, a coffee cart and a gym upstairs. Listings give day passes from roughly 100,000 IDR and about 7:00 to midnight daily, but sources disagree on Sunday, so hours are omitted. Prices not published.","address":"Jl. Raya Kerobokan No.88, Kerobokan Kelod, Kuta Utara, Badung 80361","lat":-8.66262,"lng":115.16716,"phone":"+6281238900088","access":"registration","access_note":"Walk-in day pass per third-party listings; the venue has no website of its own.","coord_precision":"venue"}
]$items$::jsonb) as x(
      slug text, city text, name text, category text, description text, address text,
      lat double precision, lng double precision, website text, phone text, opening_hours text,
      hours_source text, day_pass_price_cents integer, wheelchair text, outdoor_seating text,
      access text, access_note text, coord_precision text
    )
  loop
    select id into v_city from public.cities where slug = it.city;
    if v_city is null then
      continue;
    end if;

    v_street := coalesce(it.coord_precision, 'venue') = 'street';
    v_id := null;
    v_osm := false;
    select id, (source = 'osm') into v_id, v_osm from public.places where slug = it.slug and category = it.category;
    v_osm := coalesce(v_osm, false);
    if v_id is null then
      select p.id into v_id
        from public.places p
       where p.category = it.category
         and p.source = 'osm'
         and p.status <> 'archived'
         and not (p.id = any(v_matched))
         and public.approx_distance_km(p.lat, p.lng, it.lat, it.lng) < case when v_street then 0.5 else 0.2 end
         and (
           (not v_street and public.approx_distance_km(p.lat, p.lng, it.lat, it.lng) < 0.015)
           or (not v_street and p.category = 'library' and public.approx_distance_km(p.lat, p.lng, it.lat, it.lng) < 0.06)
           or pg_temp.nomad_same_name(p.name, it.name)
         )
       order by public.approx_distance_km(p.lat, p.lng, it.lat, it.lng)
       limit 1;
      v_osm := v_id is not null;
    end if;

    if v_id is null then
      if exists (select 1 from public.places where slug = it.slug) then
        continue;
      end if;
      insert into public.places (
        city_id, slug, name, category, status, source, description, address, lat, lng, website, phone,
        opening_hours, hours_source, day_pass_price_cents, wheelchair, outdoor_seating, access, access_note,
        last_verified_at
      ) values (
        v_city, it.slug, it.name, it.category, 'published', 'admin', it.description, it.address, it.lat, it.lng,
        it.website, it.phone, it.opening_hours, it.hours_source, it.day_pass_price_cents,
        coalesce(it.wheelchair, 'unknown'), coalesce(it.outdoor_seating, 'unknown'), it.access, it.access_note,
        date '2026-11-15'
      );
    elsif v_osm then
      v_matched := array_append(v_matched, v_id);
      v_lock := case when v_street then array['name'] else array['name', 'lat', 'lng'] end;
      if it.address is not null then v_lock := array_append(v_lock, 'address'); end if;
      if it.website is not null then v_lock := array_append(v_lock, 'website'); end if;
      if it.phone is not null then v_lock := array_append(v_lock, 'phone'); end if;
      if it.opening_hours is not null then v_lock := array_append(v_lock, 'opening_hours'); end if;
      if it.wheelchair is not null and it.wheelchair <> 'unknown' then v_lock := array_append(v_lock, 'wheelchair'); end if;
      if it.outdoor_seating is not null and it.outdoor_seating <> 'unknown' then v_lock := array_append(v_lock, 'outdoor_seating'); end if;
      update public.places set
        city_id = v_city,
        name = it.name,
        description = it.description,
        address = coalesce(it.address, address),
        lat = case when v_street then lat else it.lat end,
        lng = case when v_street then lng else it.lng end,
        website = coalesce(it.website, website),
        phone = coalesce(it.phone, phone),
        opening_hours = coalesce(it.opening_hours, opening_hours),
        hours_source = case when it.opening_hours is not null then it.hours_source else hours_source end,
        day_pass_price_cents = coalesce(it.day_pass_price_cents, day_pass_price_cents),
        wheelchair = case when it.wheelchair is not null and it.wheelchair <> 'unknown' then it.wheelchair else wheelchair end,
        outdoor_seating = case when it.outdoor_seating is not null and it.outdoor_seating <> 'unknown' then it.outdoor_seating else outdoor_seating end,
        access = it.access,
        access_note = it.access_note,
        status = case when status = 'needs_review' then 'published' else status end,
        last_verified_at = date '2026-11-15',
        locked_fields = (select coalesce(array_agg(distinct f), '{}') from unnest(locked_fields || v_lock) f)
      where id = v_id;
    else
      update public.places set
        name = it.name,
        description = it.description,
        address = it.address,
        lat = it.lat,
        lng = it.lng,
        website = it.website,
        phone = it.phone,
        opening_hours = it.opening_hours,
        hours_source = it.hours_source,
        day_pass_price_cents = it.day_pass_price_cents,
        wheelchair = coalesce(it.wheelchair, 'unknown'),
        outdoor_seating = coalesce(it.outdoor_seating, 'unknown'),
        access = it.access,
        access_note = it.access_note,
        last_verified_at = date '2026-11-15'
      where id = v_id and source = 'admin';
    end if;
  end loop;
  perform set_config('cosurfing.bulk', 'off', true);

  for v_city in select id from public.cities where slug in (
    'canggu', 'pererenan', 'umalas', 'seminyak', 'legian', 'kuta', 'uluwatu', 'jimbaran', 'nusa-dua', 'sanur', 'denpasar', 'ubud', 'sidemen', 'candidasa', 'amed', 'lovina', 'munduk', 'nusa-lembongan', 'nusa-penida', 'ericeira', 'ribamar', 'mafra', 'torres-vedras', 'santa-cruz-torres-vedras', 'lourinha'
  ) loop
    perform public.refresh_city_stats(v_city);
  end loop;
end
$nomad$;
